import type { PracticeBank, PracticeExercise, PracticeObjective, ExercisePurpose } from './practice-types';
import { studyLessons } from './study-lessons';

// Authored families vary the data for fresh practice. Every family states its own
// assumptions, reasoning and common error; examples are excluded from learner counts.
type Draft=Omit<PracticeExercise,'id'|'objectiveId'|'purpose'|'difficulty'>;
type Family={key:string;title:string;prerequisites:string[];misconceptions:string[];make:(n:number,p:ExercisePurpose)=>Draft};
const purposes:ExercisePurpose[]=['example','guided','independent','transfer','application','review'];
const round=(x:number)=>Number(x.toPrecision(12));
const fmt=(x:number)=>String(round(x));
function num(prompt:string,answer:number,setup:string,work:string,why:string,error:string,hint?:string):Draft {
  return {format:'number',prompt,answer:round(answer),tolerance:answer===0?1e-9:Math.abs(answer)*1e-6,hints:[hint||setup,why],solution:[{step:setup,why},{step:work,why:'Substitution and arithmetic apply the stated relationship to these data.'},{step:`Answer: ${fmt(answer)}.`,why:'This is the requested quantity under the assumptions in the prompt.'}],mistakes:[{answer:'Common mistake',feedback:error}]};
}
function txt(prompt:string,answers:string[],setup:string,work:string,why:string,error:string):Draft {
  return {format:'text',prompt,acceptedAnswers:answers,hints:[setup,'Check the order, signs and labels before entering the final expression.'],solution:[{step:setup,why},{step:work,why:'This follows from the stated definition or operation.'}],mistakes:[{answer:'Common mistake',feedback:error}]};
}
function choose(prompt:string,choices:string[],correct:number,reason:string,error:string):Draft {
  return {format:'choice',prompt,choices,answer:correct,acceptedAnswers:[choices[correct]],hints:['Identify which definition or physical assumption applies.','Check whether each proposed statement obeys that definition.'],solution:[{step:choices[correct],why:reason},{step:'Check the other options against the given assumptions.',why:error}],mistakes:choices.flatMap((answer,i)=>i===correct?[]:[{answer:String(i),feedback:error},{answer,feedback:error}])};
}
function rubric(prompt:string,criteria:string[],steps:[string,string][],hints:string[],error:string):Draft {
  return {format:'rubric',prompt,rubric:criteria,hints,solution:steps.map(([step,why])=>({step,why})),mistakes:[{answer:'Missing reasoning',feedback:error}]};
}
const f=(key:string,title:string,prerequisite:string,misconception:string,make:Family['make']):Family=>({key,title,prerequisites:prerequisite.split('; '),misconceptions:[misconception],make});
export const stemBanks:Record<string,PracticeBank>={};
function bank(topicId:string,scope:string,families:Family[]) {
  const objectives:PracticeObjective[]=families.map(o=>({id:`${topicId}:${o.key}`,title:o.title,prerequisites:o.prerequisites,misconceptions:o.misconceptions}));
  const exercises:PracticeExercise[]=families.flatMap(o=>purposes.map((purpose,i)=>{
    const task=o.make(i+1,purpose);
    if(purpose==='transfer') {
      const target=task.format==='number'?`The numerical result is ${fmt(task.answer!)}.`:task.format==='choice'?task.choices![task.answer!]:task.acceptedAnswers?.[0]||'Use the worked approach below.';
      return {id:`${topicId}:${o.key}:${purpose}:v1`,objectiveId:`${topicId}:${o.key}`,purpose,difficulty:'extension' as const,...rubric(`${task.prompt}\nExplain your reasoning to a learner who has only the prerequisites. Include a separate check using a definition, units, inverse operation or limiting case, and explain one likely mistake.`,['Solve the stated problem with its assumptions','Explain why the chosen operation or model applies','Check the result independently','Describe a specific error and its correction'],[...task.solution.map(s=>[s.step,s.why] as [string,string]),[target,'Compare the value or statement with the definition and assumptions.'],[task.mistakes[0]?.feedback||o.misconceptions[0],'A check should address the identified error, not just repeat the arithmetic.']],task.hints,task.mistakes[0]?.feedback||o.misconceptions[0])};
    }
    if(purpose==='review' && task.format!=='rubric') {
      return {id:`${topicId}:${o.key}:${purpose}:v1`,objectiveId:`${topicId}:${o.key}`,purpose,difficulty:'core' as const,...rubric(`Without reopening the example, reconstruct the method for this new case: ${task.prompt}\nBefore calculating, state the definition or assumption you need. After solving, explain what your answer means, and what would make your method inapplicable.`,['Identify the relevant definition or assumption','Complete the new calculation or conclusion','Interpret the answer in the stated units or basis','Name a specific limitation or misconception'],[...task.solution.map(s=>[s.step,s.why] as [string,string]),[o.misconceptions[0],'This limits how the method should be generalized.']],task.hints,task.mistakes[0]?.feedback||o.misconceptions[0])};
    }
    return {id:`${topicId}:${o.key}:${purpose}:v1`,objectiveId:`${topicId}:${o.key}`,purpose,difficulty:'core' as const,...task};
  }));
  stemBanks[topicId]={topicId,version:1,scope,reviewStatus:'awaiting-subject-review',sources:studyLessons[topicId]?.sources.map(s=>s.url)||[],objectives,exercises};
}
bank('math-whole-number-operations','Use counting and place value to combine, compare, multiply equal groups and share whole numbers. Parentheses group a calculation; multiplication and division have equal priority and run left to right. Zero can be an amount, but a zero divisor is undefined.',[
 f('combine','Add and subtract amounts and check with the inverse','Count whole numbers; Understand place value','Subtraction does not commute: exchanging the amounts changes the result.',(n,p)=>{const a=137+29*n,b=48+7*n;return num(p==='application'?`A library has ${a} books and receives ${b} more. How many books are there?`:`Find ${a} + ${b}.`,a+b,'Add ones, tens and hundreds, carrying when a column reaches ten.',`${a} + ${b} = ${a+b}; checking ${a+b} − ${b} returns ${a}.`,'Place value makes ten ones equal one ten.','Do not concatenate digits or drop a carried ten.');}),
 f('groups','Connect multiplication and division to equal groups','Add equal amounts; Know small multiplication facts','Division answers depend on whether you want group size or number of groups.',(n,p)=>{const groups=n+3,size=n+4;return n%2?num(`There are ${groups} equal boxes with ${size} counters each. Find the total counters.`,groups*size,'Multiply the number of groups by the size of each group.',`${groups} × ${size} = ${groups*size}.`,'Repeated equal groups are multiplication.','Adding group count and size counts neither the counters nor the boxes.'):num(`${groups*size} counters are shared equally between ${groups} boxes. How many counters go in one box?`,size,'Divide the total by the number of equal boxes.',`${groups*size} ÷ ${groups} = ${size}.`,'Division reverses multiplication.','Dividing the number of boxes by the counters reverses the requested ratio.');}),
 f('order','Evaluate grouping and equal-priority operations','Read parentheses; Multiply and divide','Multiplication does not outrank division: both run left to right.',(n,p)=>{const a=n+2;return n%2?num(`Evaluate (${a} + 4) × 3 − 5.`,(a+4)*3-5,'Do the parentheses, then multiply, then subtract.',`(${a}+4)×3−5 = ${a+4}×3−5 = ${(a+4)*3-5}.`,'Grouping controls what is multiplied.','Multiplying 4 by 3 before resolving parentheses changes the expression.'):num(`Evaluate ${a*12} ÷ 3 × 2 + 1.`,a*8+1,'Perform division and multiplication from left to right.',`${a*12}÷3×2+1 = ${a*4}×2+1 = ${a*8+1}.`,'Division and multiplication have the same priority.','Dividing by 3×2 would insert parentheses that were not given.');}),
 f('estimate-zero','Use estimates and explain zero cases','Round to tens; Understand equal sharing','0 ÷ a is zero for nonzero a; a ÷ 0 has no defined quotient.',(n,p)=>{if(n%2===0)return choose(`Which statement correctly describes ${n+5} ÷ 0?`,['It is 0.','It is undefined because no number times 0 equals the nonzero dividend.','It equals the dividend.'],1,'A quotient q would require 0×q to equal a nonzero amount.','Multiplication by zero always gives zero; a zero divisor cannot reverse it.');const a=141+10*n,b=78+10*n;return num(`Estimate ${a} + ${b} by rounding each addend to the nearest ten.`,Math.round(a/10)*10+Math.round(b/10)*10,'Round each amount separately to the nearest ten.',`${a} → ${Math.round(a/10)*10}; ${b} → ${Math.round(b/10)*10}; add the rounded amounts.`,'An estimate uses nearby easy amounts to check the size of the exact answer.','Rounding the exact sum is a different requested procedure.');})
]);
// Six extra tasks make the introductory model bank 26 learner tasks plus four examples.
{
 const b=stemBanks['math-whole-number-operations'];
 const extras:[string,string,Draft][]=[
 ['combine','independent',num('Find 803 − 267.',536,'Regroup one hundred as ten tens, then one ten as ten ones.','803 − 267 = 536; 536 + 267 = 803.','Regrouping preserves the amount while making subtraction possible.','Subtracting the smaller digit from the larger in every column gives the wrong difference.')],
 ['combine','review',num('A museum sold 742 tickets and refunded 185. In a later session, find the tickets still sold.',557,'Subtract refunded tickets from sold tickets.','742 − 185 = 557.','Refunds remove tickets from the sale count.','Adding refunds would increase the sale count.')],
 ['groups','independent',num('Find 0 × 19.',0,'Think of zero groups of nineteen.','0 × 19 = 0.','No groups contain no objects.','Zero is not the multiplicative identity; one is.')],
 ['groups','transfer',num('31 pupils travel in vans holding at most 6 pupils. Find the minimum number of vans.',6,'Divide 31 by 6 and round upward to fit everyone.','31 = 5×6 + 1, so a sixth van is needed.','A remaining pupil still needs a seat.','Rounding down leaves one pupil without transport.')],
 ['order','application',num('A club buys 4 kits at 9 dollars each and pays a 7 dollar delivery fee. Find the total dollars.',43,'Use 4×9 + 7.','4×9+7 = 36+7 = 43.','Delivery is charged once, while kit cost is repeated four times.','4×(9+7) charges delivery four times.')],
 ['order','review',rubric('A learner says 18 − 6 + 2 = 10 because addition comes first. Correct the answer and explain the order.',['Obtain 14','Explain addition and subtraction have equal priority','Show 18−6=12, then 12+2=14'],[['Evaluate 18−6=12, then 12+2=14.','Addition and subtraction run left to right.'],['The learner implicitly evaluated 18−(6+2).','That grouping was not present.']],['Addition and subtraction have the same priority.','Read from left to right.'],'Do not use a mnemonic to give addition priority over subtraction.')],
 ['groups','independent',num('Find 84 ÷ 7.',12,'Find the number that multiplied by 7 gives 84.','7×12=84, so 84÷7=12.','Division reverses multiplication.','84−7 gives one subtraction, not the number of equal groups.')],
 ['estimate-zero','independent',num('Find 0 ÷ 7.',0,'Share zero objects among seven groups.','Each group receives zero; 7×0=0.','A nonzero divisor gives a unique quotient even with a zero dividend.','0÷7 is defined and zero; 7÷0 is undefined.')]
 ];
 for(const [key,p,draft] of extras)b.exercises.push({id:`${b.topicId}:${key}:extra-${b.exercises.length}:v1`,objectiveId:`${b.topicId}:${key}`,purpose:p as ExercisePurpose,difficulty:'core',...draft});
}
bank('math-fractions-and-decimals','A fraction is a quotient of integers with nonzero denominator. Equivalent fractions describe the same amount. Use common denominators for addition and place value for decimal calculations.',[
 f('equivalence','Reduce fractions and compare representations','Multiply and divide; Know factors','Changing only the denominator changes the value.',n=>txt(`Reduce ${3*(n+1)}/${6*(n+1)} to lowest terms.`,['1/2','0.5'],'Divide numerator and denominator by their common factor.',`${3*(n+1)}/${6*(n+1)} = 1/2.`,'Dividing both parts by the same nonzero amount preserves the quotient.','Do not subtract a common amount from numerator and denominator.')),
 f('add','Add fractions with different denominators','Equivalent fractions; Add whole numbers','Denominators are not added.',n=>txt(`Find ${n}/6 + 1/3 as a reduced fraction.`,[(n+2)%6===0?String((n+2)/6):`${(n+2)/gcd(n+2,6)}/${6/gcd(n+2,6)}`], 'Rewrite 1/3 as 2/6.',`${n}/6 + 2/6 = ${n+2}/6; reduce common factors.`,'Common denominators make the pieces the same size.','Adding denominators would change the size of each piece.')),
 f('multiply-divide','Multiply fractions and divide by a nonzero fraction','Multiply integers; Meaning of reciprocal','Division by 1/2 doubles the amount rather than halves it.',n=>num(`${n+2}/4 litres are divided into portions of 1/2 litre. How many portions, allowing a partial portion?`,(n+2)/2,'Divide (n+2)/4 by 1/2 by multiplying by 2.',`(${n+2}/4)×2 = ${(n+2)/2}.`,'A reciprocal converts division into multiplication.','Multiplying by 1/2 answers a different question.')),
 f('decimals','Use decimal place value in money or measures','Place value; Fractions of ten','Align decimal points for addition; count decimal places for multiplication.',n=>num(`${n+2}.50 metres of ribbon cost 1.20 dollars per metre. Find the cost in dollars.`,(n+2.5)*1.2,'Multiply the length by the cost per metre.',`${n+2.5}×1.20 = ${fmt((n+2.5)*1.2)} dollars.`,'Metres cancel with dollars per metre.','Ignoring decimal places makes the result one hundred times too large.'))
]);
function gcd(a:number,b:number):number {return b?gcd(b,a%b):a;}
bank('math-ratios-and-rates','A ratio compares quantities; a rate compares quantities with different units. Proportion means two ratios are equal. Direct proportion assumes a fixed rate and no fixed starting fee.',[
 f('ratio','Scale a ratio while preserving its order','Fractions; Multiplication','A ratio 2:3 does not mean 2 out of 3 in the total.',n=>num(`A drink mixes juice and water in ratio 2:3. It uses ${2*(n+1)} cups of juice. Find cups of water.`,3*(n+1),'The juice amount is 2 times a scale factor.',`Scale factor = ${n+1}; water = 3×${n+1} = ${3*(n+1)}.`,'Both ratio parts must be scaled equally.','The total has five parts, so water is three fifths of the total.')),
 f('unit-rate','Calculate and compare a unit rate','Division; Units','A lower total price need not mean a lower unit price.',n=>num(`${n+2} kilograms cost ${3*(n+2)} dollars. Find dollars per kilogram.`,3,'Divide dollars by kilograms.',`${3*(n+2)}/${n+2} = 3 dollars/kg.`,'A unit rate describes one unit of the denominator quantity.','Reversing the division gives kilograms per dollar.')),
 f('percent','Find percent changes from the original amount','Decimals; Fractions','Percent increase is measured against the original amount.',n=>num(`A price increases from ${20*n} to ${25*n} dollars. Find the percentage increase as a number, without a percent sign.`,25,'Compute (new−original)/original × 100.',`(${25*n}−${20*n})/${20*n} ×100 = 25.`,'The original price is the comparison base.','Dividing by the new price would give 20%, a different comparison.')),
 f('rate-model','Distinguish proportional costs from a fixed fee','Multiply rates; Add amounts','A fixed fee prevents total cost from being proportional to usage.',n=>num(`A taxi charges 4 dollars plus 2 dollars per kilometre. Find the charge for ${n+3} kilometres.`,4+2*(n+3),'Use C = 4 + 2d.',`C = 4 + 2×${n+3} = ${4+2*(n+3)}.`,'The fixed fee is paid once; distance adds a variable charge.','Multiplying 6 by distance repeats the fixed fee for every kilometre.'))
]);
bank('math-equations-and-inequalities','Solve by performing the same reversible operation on both sides. An inequality compares size; multiplying or dividing by a negative reverses its direction. Solutions must satisfy the original statement.',[
 f('linear','Solve and check a linear equation','Signed arithmetic; Distributive property','Moving a term is shorthand for an operation on both sides.',n=>num(`Solve 3x + ${n+2} = ${4*n+8}. Enter x.`,n+2,'Subtract the constant on both sides, then divide by 3.',`3x = ${3*n+6}; x = ${n+2}.`,'Equal operations preserve equality.','Dividing only 3x before subtracting the constant leaves the sides unequal.')),
 f('parentheses','Solve an equation with grouped terms','Distribute multiplication; Linear equations','The multiplier applies to every term in parentheses.',n=>num(`Solve 2(x − ${n}) = ${2*n+6}.`,2*n+3,'Divide both sides by 2, then add n.',`x−${n}=${n+3}; x=${2*n+3}.`,'Dividing the entire grouped expression reverses multiplication.','2(x−n) is 2x−2n, not 2x−n.')),
 f('inequality','Solve a negative-coefficient inequality','Order of signed numbers; Linear equations','Multiplication by a negative reverses the order.',n=>txt(`Solve −2x < ${2*n}. Write the inequality.`,[`x > -${n}`,`x>-${n}`],'Divide by −2 and reverse < to >.',`x > −${n}.`,'A negative scale reverses the number line.','Keeping < after dividing by a negative selects the wrong side.')),
 f('model','Translate a budget into an inequality','Fixed and variable cost; Inequalities','A budget maximum uses ≤, and whole items require rounding down.',n=>num(`A pass costs 5 dollars, and rides cost 3 dollars each. With ${5+3*(n+2)+2} dollars, what is the maximum whole number of rides?`,n+2,'Use 5+3r ≤ the budget, then require an integer r.',`r ≤ ${fmt((3*(n+2)+2)/3)}; maximum integer r = ${n+2}.`,'The budget cannot be exceeded and a ride cannot be purchased fractionally.','Rounding up exceeds the budget.'))
]);
bank('math-coordinates-and-graphs','Ordered pairs (x,y) give horizontal then vertical position. Slope is change in y divided by change in x. A line y=mx+b has slope m and vertical intercept b.',[
 f('coordinates','Read points, quadrants and displacement','Signed numbers; Number lines','The first coordinate is horizontal, not vertical.',n=>txt(`Point P is (${n}, −${n+2}). Which quadrant contains P?`,['IV','4','quadrant iv','fourth quadrant'],'Inspect the signs of x and y.','x is positive and y is negative, so P is in quadrant IV.','Quadrants are numbered counterclockwise from positive x and positive y.','A negative y means below the horizontal axis, not left of the vertical axis.')),
 f('slope','Find slope from two points','Subtract signed numbers; Divide','The order of points must be consistent in numerator and denominator.',n=>num(`Find the slope through (${n}, 2) and (${n+3}, ${2+3*(n+1)}).`,n+1,'Use (y₂−y₁)/(x₂−x₁).',`Slope = ${3*(n+1)}/3 = ${n+1}.`,'Slope measures vertical change per horizontal unit.','Using x change over y change gives the reciprocal.')),
 f('line','Evaluate a straight-line model','Multiply signed numbers; Coordinate pairs','The intercept is the value at x=0, not the slope.',n=>num(`A line is y = 2x − 3. Find y at x=${n+2}.`,2*n+1,'Substitute the x coordinate into the line equation.',`y = 2×${n+2}−3 = ${2*n+1}.`,'A point on a graph obeys its equation.','Do not multiply the intercept by x.')),
 f('distance','Use coordinates to calculate distance','Squares; Square roots; Pythagorean theorem','Horizontal plus vertical distance is not straight-line distance.',n=>num(`A map uses kilometres. Find the straight-line distance from (0,0) to (${3*n},${4*n}).`,5*n,'Use d = √(x²+y²).',`d = √(${9*n*n}+${16*n*n}) = ${5*n} km.`,'Perpendicular coordinate differences form a right triangle.','Adding x and y gives the length of a right-angle path.'))
]);
bank('math-geometry-and-measurement','Perimeter measures boundary length; area measures surface in square units; volume measures space in cubic units. Use right-triangle relationships only when a right angle is established.',[
 f('area','Calculate perimeter and area with correct units','Multiplication; Units of length','Area and perimeter are different quantities.',n=>num(`A rectangle is ${n+3} cm long and ${n+1} cm wide. Find its area in cm².`,(n+3)*(n+1),'Multiply length by width.',`A = ${n+3}×${n+1} = ${(n+3)*(n+1)} cm².`,'A rectangular array counts unit squares.','2(length+width) gives perimeter in cm.')),
 f('triangle','Use right-triangle lengths','Squares and roots; Identify a right angle','Pythagoras applies to right triangles, and the hypotenuse is opposite the right angle.',n=>num(`A right triangle has perpendicular legs ${6*n} m and ${8*n} m. Find the hypotenuse in m.`,10*n,'Square both legs, add, then take the square root.',`c = √(${36*n*n}+${64*n*n}) = ${10*n} m.`,'The right angle guarantees a²+b²=c².','Adding the legs does not give the hypotenuse.')),
 f('volume','Find volume and scale effects','Area; Cubic units','Doubling every length multiplies volume by eight.',n=>num(`A box measures ${n+1} cm by 3 cm by 4 cm. Find its volume in cm³.`,12*(n+1),'Multiply all three perpendicular lengths.',`V = ${n+1}×3×4 = ${12*(n+1)} cm³.`,'Layers of unit cubes fill a rectangular box.','Multiplying just two dimensions gives an area.')),
 f('circles','Use circle circumference and area','Meaning of radius; π','Diameter is twice radius; area uses radius squared.',n=>num(`A circle has radius ${n+1} m. Use π=3.141592653589793 to find its area in m².`,Math.PI*(n+1)**2,'Use A=πr².',`A = π×${n+1}² = ${fmt(Math.PI*(n+1)**2)} m².`,'The circle formula uses radius rather than diameter.','2πr is a circumference, measured in metres.'))
]);
bank('math-data-and-probability','Mean is sum divided by count; median is the middle of sorted values. Probability uses an explicitly stated equally likely sample space. Independence permits multiplying separate-event probabilities.',[
 f('center','Compare mean and median','Sort numbers; Division','An outlier changes mean more directly than median.',n=>num(`Find the mean of ${n}, ${n+2}, ${n+4}, ${n+6}.`,n+3,'Add the four values and divide by four.',`Mean = ${4*n+12}/4 = ${n+3}.`,'Each observation contributes equally to the mean.','Dividing by three mistakes the number of gaps for the number of data points.')),
 f('spread','Calculate range and inspect outliers','Order numbers; Subtraction','Range uses maximum minus minimum, not their sum.',n=>num(`Find the range of 2, ${n+3}, ${n+7}, ${n+12}.`,n+10,'Find the smallest and largest observations.',`Range = ${n+12}−2 = ${n+10}.`,'Range measures total observed spread.','Counting observations does not measure spread.')),
 f('single-probability','Count favourable and possible outcomes','Fractions; Equally likely outcomes','Probability depends on the sampling procedure.',n=>num(`A bag contains ${n+1} red and ${2*(n+1)} blue identical balls. One is selected uniformly. Find P(red).`,1/3,'Divide the red count by the total count.',`P(red)=${n+1}/${3*(n+1)}=1/3.`,'Each individual ball is equally likely.','Two colours do not imply each colour has probability one half.')),
 f('independence','Distinguish independent from dependent draws','Multiply fractions; Conditional probability','Without replacement the second-draw probability changes.',n=>num(`A bag has ${n+2} red and ${n+2} blue balls. Draw twice without replacement. Find P(both red).`,(n+1)/(2*(2*n+3)),'Multiply P(first red) by P(second red given first red).',`P = 1/2 × ${n+1}/${2*n+3} = ${fmt((n+1)/(2*(2*n+3)))}.`,'After one red is removed both red count and total fall by one.','Using 1/2 twice assumes replacement or independence.'))
]);
bank('math-functions-and-graphs','A function assigns exactly one output to each allowed input. Domain lists allowed inputs; composition applies one function then another. An inverse reverses a function only when each output has one originating input.',[
 f('evaluate','Evaluate linear and quadratic functions','Signed arithmetic; Powers','f(x) is an output label, not f multiplied by x.',n=>num(`Let f(x)=x²−2x+3. Find f(${n}).`,n*n-2*n+3,'Substitute the input everywhere x occurs.',`f(${n})=${n*n}−${2*n}+3=${n*n-2*n+3}.`,'The formula defines the assigned output.','Square the entire input before subtracting 2x.')),
 f('domain','Find restrictions on a function domain','Division; Solving a linear equation','An undefined denominator cannot be included in a domain.',n=>txt(`For real f(x)=1/(x−${n}), which single input must be excluded?`,[String(n),`x=${n}`,`x = ${n}`],'Set the denominator equal to zero.',`x−${n}=0 gives x=${n}.`,'Division by zero is undefined.','A zero numerator would be allowed; the denominator is the restriction.')),
 f('composition','Calculate a composition in the stated order','Evaluate functions; Parentheses','f(g(x)) and g(f(x)) usually differ.',n=>num(`f(x)=2x+1 and g(x)=x². Find f(g(${n+1})).`,2*(n+1)**2+1,'Apply g first, then feed that output into f.',`g(${n+1})=${(n+1)**2}; f(${(n+1)**2})=${2*(n+1)**2+1}.`,'The inner expression supplies the outer input.','Squaring 2x+1 calculates g(f(x)), the reversed order.')),
 f('inverse','Reverse an invertible function','Linear equations; Function inputs','An inverse is not generally the reciprocal 1/f(x).',n=>num(`f(x)=3x−2. Find the input whose output is ${3*n+1}.`,n+1,'Solve 3x−2 equal to the stated output.',`3x=${3*n+3}; x=${n+1}.`,'An inverse solves for the original input.','Taking 1/(3x−2) does not undo the function.'))
]);
bank('math-polynomial-patterns','Polynomials combine nonnegative integer powers of a variable. Expand by distributing every term; factor by reversing expansion. A root makes the polynomial zero, and the zero-product property applies when a product equals zero.',[
 f('expand','Expand products of linear terms','Distribution; Powers','Both cross terms are needed in a squared binomial.',n=>txt(`Expand (x+${n})(x+2). Use x^2 notation.`,[`x^2+${n+2}x+${2*n}`,`x^2 + ${n+2}x + ${2*n}`],'Multiply every term in the first bracket by every term in the second.',`x²+2x+${n}x+${2*n}=x²+${n+2}x+${2*n}.`,'Distributivity accounts for all four products.','Dropping the cross terms changes the polynomial.')),
 f('factor','Factor a quadratic through its roots','Expand binomials; Integer factors','A factor sign is opposite the corresponding root sign.',n=>txt(`Factor x²−${n+3}x+${3*n}. Use (x-a)(x-b).`,[`(x-${n})(x-3)`,`(x-3)(x-${n})`],'Find numbers with sum −(n+3) and product 3n.',`The numbers are −${n} and −3, giving (x−${n})(x−3).`,'Expanding the factors recovers both coefficients.','Positive factors would give a positive middle coefficient.')),
 f('roots','Use the zero-product property','Factoring; Solve linear equations','A product being zero requires at least one factor to be zero.',n=>num(`One root of (x−${n})(x+2)=0 is −2. Find the other root.`,n,'Set the other factor x−n equal to zero.',`x−${n}=0 gives x=${n}.`,'Over real numbers a nonzero product cannot equal zero.','Setting the sum of the factors to zero is not the zero-product property.')),
 f('remainder','Evaluate a polynomial remainder','Substitution; Polynomial division','The remainder for division by x−a is f(a), not f(−a).',n=>num(`Find the remainder when f(x)=x³−2x+1 is divided by x−${n}.`,n**3-2*n+1,'Use the remainder theorem: remainder = f(a).',`f(${n})=${n**3}−${2*n}+1=${n**3-2*n+1}.`,'At x=a the multiple of x−a vanishes.','The divisor x−n vanishes at positive n.'))
]);
bank('math-exponential-models','A discrete exponential model multiplies by a fixed factor each time step. A growth factor is 1+r; a decay factor is 1−r. Logarithms undo exponentiation and continuous growth uses exp(rt).',[
 f('growth','Calculate discrete compound growth','Powers; Percent as decimal','Repeated percent growth is multiplicative, not additive.',n=>num(`A population starts at 100 and grows by 10% per year. Find the model population after ${n} years (allow decimals).`,100*1.1**n,'Use P=100(1.1)^t.',`P=100×1.1^${n}=${fmt(100*1.1**n)}.`,'Each year applies the rate to the new population.','Adding 10 each year uses a fixed increase.')),
 f('decay','Model repeated decay with half-lives','Powers; Fractions','A half-life halves the remaining amount, not the original amount every interval.',n=>num(`A sample starts at 64 mg. After ${n} full half-lives, how many mg remain?`,64/2**n,'Multiply by 1/2 once per half-life.',`64(1/2)^${n}=${64/2**n} mg.`,'Decay acts on the remaining sample.','Subtracting 32 mg repeatedly becomes negative and is not exponential decay.')),
 f('logarithms','Solve for the exponent in a growth model','Exponents; Meaning of logarithm','A logarithm finds an exponent, not a multiplication factor.',n=>num(`Solve 2^t=${2**(n+1)}. Enter t.`,n+1,'Rewrite the right side as a power of 2.',`${2**(n+1)}=2^${n+1}, so t=${n+1}.`,'The positive-base exponential is one-to-one.','Dividing the right side by 2 does not undo exponentiation.')),
 f('continuous','Distinguish continuous rate from annual percentage','Exponential function; Rate units','exp(r)−1 is the effective one-period increase.',n=>num(`Continuous growth has P(t)=50 exp(0.2t), t in years. Find P(${n}) using e≈2.718281828459045.`,50*Math.exp(.2*n),'Substitute t into exp(0.2t).',`P=50exp(${fmt(.2*n)})=${fmt(50*Math.exp(.2*n))}.`,'The continuous rate accumulates throughout time.','50(1.2)^t is a different discrete model.'))
]);
bank('math-trigonometric-relationships','In a right triangle sine is opposite/hypotenuse, cosine adjacent/hypotenuse and tangent opposite/adjacent. Radians measure angle by arc length divided by radius. State degree or radian units before evaluating.',[
 f('ratios','Use a right-triangle ratio','Right triangles; Fractions','Opposite and adjacent depend on the chosen angle.',n=>num(`A right triangle has opposite leg ${3*n}, adjacent leg ${4*n}, hypotenuse ${5*n} relative to θ. Find sin θ.`,.6,'Divide opposite by hypotenuse.',`sin θ=${3*n}/${5*n}=0.6.`,'Sine is the opposite-to-hypotenuse ratio.','4/5 is cosine for this angle.')),
 f('radians','Convert degrees to radians','Fractions; π','Degrees and radians are two units for the same angle.',n=>num(`Convert ${30*n} degrees to radians. Enter a decimal.`,Math.PI*n/6,'Multiply degrees by π/180.',`${30*n}×π/180=${n}π/6=${fmt(Math.PI*n/6)} rad.`,'A half turn is both 180° and π radians.','Multiplying by 180/π converts in the opposite direction.')),
 f('height','Apply tangent to an accessible height','Ratios; Calculator angle units','Tangent uses opposite/adjacent, not hypotenuse.',n=>num(`From ${5*n} m away on level ground, a roof is seen at elevation 45°. Neglect eye height. Find the roof height in m.`,5*n,'Use height = horizontal distance × tan(45°).',`h=${5*n}×1=${5*n} m.`,'Level ground creates a right triangle with the horizontal distance adjacent.','Using sine would require the slanted line-of-sight distance.')),
 f('identity','Apply sin²θ+cos²θ=1 with a quadrant','Squares; Square roots; Signs','The square root sign depends on the quadrant.',n=>{const a=n+1,b=Math.sqrt(1-1/a**2);return num(`An acute angle has sin θ=1/${a}. Find cos θ.`,b,'Use cos²θ=1−sin²θ and choose the positive root.',`cos θ=√(1−1/${a*a})=${fmt(b)}.`,'Cosine is positive for an acute angle.','1−sin θ omits the squares required by the identity.');})
]);
bank('math-limits-and-continuity','A limit describes values approached near an input, not necessarily the value at that input. Continuity at a requires an existing value, an existing two-sided limit and equality between them. Algebraic cancellation is valid away from a removable hole.',[
 f('substitution','Evaluate continuous polynomial limits','Substitution; Polynomials','Limits of continuous polynomials equal their point values.',n=>num(`Find lim as x→${n} of (x²+2x).`,n*n+2*n,'Use continuity of a polynomial and substitute.',`${n}²+2×${n}=${n*n+2*n}.`,'Polynomials are continuous at every real input.','A limit does not automatically require dividing by a small number.')),
 f('removable','Simplify a removable discontinuity','Factor difference of squares; Fractions','Cancel factors, not separate additive terms.',n=>num(`Find lim as x→${n} of (x²−${n*n})/(x−${n}).`,2*n,'Factor the numerator, then cancel x−n for x≠n.',`(x−${n})(x+${n})/(x−${n})=x+${n}; limit=${2*n}.`,'Near the point the simplified expression has the same values.','The original quotient is undefined at the point, but its limit can exist.')),
 f('one-sided','Compare one-sided limits','Absolute value; Signed quantities','Opposing one-sided limits mean no two-sided limit.',n=>choose(`For f(x)=(x−${n})/|x−${n}|, which describes lim x→${n}?`,['It is 0.','It is 1.','It does not exist: the left limit is −1 and the right limit is 1.'],2,'The sign changes across the point, so the two sides approach different values.','An average of one-sided limits is not a two-sided limit.')),
 f('continuity','Choose a value that fills a removable hole','Limits; Piecewise definitions','Defining a value can repair a removable hole but cannot repair a jump.',n=>num(`Let f(x)=(x²−${n*n})/(x−${n}) for x≠${n}; f(${n})=k. Which k makes f continuous?`,2*n,'Set the point value equal to the limit.',`The cancelled expression is x+${n}, so k=${2*n}.`,'Continuity requires value and two-sided limit to agree.','Choosing zero just because the original numerator is zero ignores the nearby ratio.'))
]);
bank('math-derivatives-and-integrals','Derivatives measure instantaneous change; definite integrals accumulate signed area. Use polynomial differentiation, product and chain rules, antiderivatives and the fundamental theorem. Inputs here use real functions on domains where the stated formulas are differentiable.',[
 f('product','Differentiate a product, then evaluate','Power rule; Multiplication; Function notation','The derivative of a product is not the product of derivatives.',n=>num(`f(x)=x² exp(x). Find f′(${n}), using e≈2.718281828459045.`,Math.exp(n)*(n*n+2*n),'Use (uv)′=u′v+uv′.',`f′(x)=exp(x)(2x+x²); f′(${n})=exp(${n})×${n*n+2*n}=${fmt(Math.exp(n)*(n*n+2*n))}.`,'Both factors change, so each contributes a term.','2x exp(x) alone omits the change in exp(x).')),
 f('chain','Differentiate a composed function','Power rule; Function composition','The inner derivative multiplies the outer derivative.',n=>num(`g(x)=(3x+1)^4. Find g′(${n}).`,12*(3*n+1)**3,'Apply the power rule outside, then multiply by the derivative of 3x+1.',`g′(x)=4(3x+1)^3×3; g′(${n})=${12*(3*n+1)**3}.`,'The chain rule converts change in the inner quantity to change in x.','4(3x+1)^3 is missing the inner derivative 3.')),
 f('definite','Evaluate a definite integral with endpoints','Antiderivatives; Powers; Subtraction','A definite integral uses F(b)−F(a) and may be signed.',n=>num(`Evaluate ∫ from 0 to ${n} of (3x²−2x+1) dx.`,n**3-n*n+n,'An antiderivative is F(x)=x³−x²+x.',`F(${n})−F(0)=${n**3}−${n*n}+${n}=${n**3-n*n+n}.`,'The fundamental theorem relates accumulated change to endpoint values.','Substituting into the integrand gives its height, not accumulated area.')),
 f('accumulation','Use substitution and accumulated change','Chain rule; Definite integrals; Rate units','Integrating a rate gives change, not necessarily the final amount.',n=>num(`A tank initially holds 10 L and has net inflow r(t)=2t exp(t²) L/min for 0≤t≤${n/2} min. Find final litres.`,9+Math.exp((n/2)**2),'Use u=t² so du=2t dt, and add the initial 10 L.',`Change=exp(${(n/2)**2})−1; final=10+change=${fmt(9+Math.exp((n/2)**2))} L.`,'The chain rule identifies the antiderivative exp(t²); rate integration gives volume change.','Omitting the initial volume reports only the inflow.'))
]);
bank('math-sequences-and-series','A sequence is an ordered list; a series adds its terms. Arithmetic sequences add a fixed difference; geometric sequences multiply by a fixed ratio. An infinite geometric series converges only when the ratio has absolute value below one.',[
 f('arithmetic','Find an arithmetic sequence term','Signed addition; Index counting','The nth term uses n−1 changes from the first term.',n=>num(`A sequence starts at 5 and adds 3 each term. Find term ${n+3}, with first term indexed 1.`,5+3*(n+2),'Use a_k=a₁+(k−1)d.',`a_${n+3}=5+${n+2}×3=${5+3*(n+2)}.`,'There are k−1 intervals between the first and kth terms.','Using k increments adds one extra difference.')),
 f('finite-sum','Sum a finite arithmetic series','Arithmetic sequence; Mean of endpoints','A sum includes all terms, not just the last one.',n=>num(`Find 1+2+...+${n+4}.`,(n+4)*(n+5)/2,'Pair the first and last terms, or use k(k+1)/2.',`S=${n+4}×${n+5}/2=${(n+4)*(n+5)/2}.`,'Paired endpoint sums are equal.','k² overcounts because the average term is (k+1)/2.')),
 f('geometric','Find a geometric term','Powers; Multiplication','Geometric patterns have fixed ratios rather than fixed differences.',n=>num(`A sequence begins 2,6,18,... . Find term ${n+2}, indexed from 1.`,2*3**(n+1),'Use a_k=2×3^(k−1).',`a_${n+2}=2×3^${n+1}=${2*3**(n+1)}.`,'Each new term multiplies the previous term by 3.','Adding 4 each time only matches the first two terms.')),
 f('infinite','Check convergence and sum an infinite geometric series','Geometric ratio; Fractions','A positive infinite series need not diverge if its terms shrink fast enough.',n=>num(`Find the infinite sum ${n}+${n}/2+${n}/4+... .`,2*n,'The ratio is 1/2, so use a/(1−r).',`S=${n}/(1−1/2)=${2*n}.`,'For |r|<1, the remainder tends to zero.','Dividing by 1+r gives an incorrect series total.'))
]);
bank('math-vectors-and-matrices','Vectors carry components in a fixed coordinate order. Dot products use paired components. Matrix multiplication uses row-by-column sums and requires matching inner dimensions; changing order usually changes the product.',[
 f('vector-sum','Add vectors and inspect components','Ordered pairs; Signed addition','Vector addition acts componentwise.',n=>txt(`Add vectors (${n},2) and (−1,${n+3}). Enter (x,y).`,[`(${n-1},${n+5})`,`(${n-1}, ${n+5})`],'Add horizontal components and vertical components separately.',`(${n}−1,2+${n+3})=(${n-1},${n+5}).`,'Corresponding components use the same coordinate axes.','Adding every number into one scalar loses direction.')),
 f('dot','Calculate a dot product and interpret orthogonality','Multiply components; Add signed numbers','A dot product is a scalar, not a componentwise vector.',n=>num(`Find (${n},2) · (3,−1).`,3*n-2,'Multiply corresponding components and sum.',`${n}×3+2×(−1)=${3*n-2}.`,'The dot product sums contributions along common axes.','Writing (3n,−2) stops before taking the scalar sum.')),
 f('matrix-product','Multiply two 2×2 matrices in a stated order','Signed arithmetic; Rows and columns','Matrix multiplication is not entrywise multiplication.',n=>txt(`A=[[1,${n}],[2,1]], B=[[3,1],[1,2]]. Find AB. Enter [[a,b],[c,d]].`,[`[[${n+3},${2*n+1}],[7,4]]`,`[[${n+3}, ${2*n+1}], [7, 4]]`],'For each entry multiply a row of A by a column of B and add.',`AB=[[1×3+${n}×1,1×1+${n}×2],[2×3+1×1,2×1+1×2]]=[[${n+3},${2*n+1}],[7,4]].`,'The output component combines intermediate coordinates via row-column sums.','Entrywise products [[3,n],[2,2]] are not AB.')),
 f('linear-system','Solve a matrix-defined linear system','Linear equations; Elimination','Each matrix row gives one equation.',n=>txt(`Solve [[1,1],[1,−1]][[x],[y]]=[[${2*n+2}],[2]]. Enter (x,y).`,[`(${n+2},${n})`,`(${n+2}, ${n})`],'Add x+y=2n+2 and x−y=2 to eliminate y.',`2x=${2*n+4}; x=${n+2}; y=${n}.`,'Adding equations preserves their common solution.','Solving each row as if it had only one variable ignores the coupling.'))
]);
bank('math-proofs-and-optimization','A proof explains why a claim follows for every case under stated assumptions. Counterexamples disprove universal claims. Optimization finds candidates and checks endpoints or second derivatives; a stationary point alone does not guarantee a maximum.',[
 f('proof','Prove a parity claim with algebra','Integer arithmetic; Meaning of even and odd','Several examples support a pattern but do not prove every case.',n=>rubric(`Prove that the sum of two odd integers is even. Illustrate with ${2*n+1} and ${2*n+3}.`,['Represent odd integers as 2a+1 and 2b+1','Factor their sum as 2(a+b+1)','State a+b+1 is an integer','Include the requested illustration'],[['Let the integers be 2a+1 and 2b+1.','This represents every odd integer, including negative ones.'],['Their sum is 2(a+b+1).','An integer multiplied by 2 is even.'],[`${2*n+1}+${2*n+3}=${4*n+4}.`,'The illustration agrees with the proof but does not replace it.']],['Use the definition of odd, not just a list of odd numbers.','Factor a 2 from the complete sum.'],'Examples alone do not prove a universal claim.')),
 f('counterexample','Disprove a universal claim','Logical quantifiers; Squaring','One valid counterexample is enough to disprove all.',n=>num(`The claim is: for every real x, x²≥x. Test x=1/${n+1}. Find x²−x.`,1/(n+1)**2-1/(n+1),'Subtract x from x² for this proposed counterexample.',`x²−x=1/${(n+1)**2}−1/${n+1}=${fmt(1/(n+1)**2-1/(n+1))}<0.`,'A negative difference violates the claimed inequality.','Testing only integers misses real counterexamples between zero and one.')),
 f('stationary','Find and classify a stationary point','Derivative power rule; Second derivative','A zero derivative can identify a minimum, maximum or neither.',n=>num(`f(x)=x²−${2*n}x+3. Find the x coordinate of its global minimum.`,n,'Set f′(x)=2x−2n=0; check f″(x)=2>0.',`x=${n}; the upward quadratic has its global minimum here.`,'Positive curvature and an upward quadratic establish the minimum.','Reporting the function value instead of x answers a different question.')),
 f('constraint','Optimize a rectangle under a perimeter constraint','Area; Derivatives; Endpoints','Maximum area for fixed perimeter requires comparing feasible shapes.',n=>num(`A rectangle has perimeter ${8*(n+1)} m. Find the side length of the square that maximizes its area.`,2*(n+1),'With x+y=P/2, area is x(P/2−x).',`A′=P/2−2x=0 gives x=P/4=${2*(n+1)} m; A″=−2.`,'The concave quadratic has a maximum; degenerate endpoint areas are zero.','Using P/2 as one side leaves no positive length for the other.'))
]);
bank('physics-units-and-measurement','Measurements pair a value with a unit and have limited precision. SI is a shared system including metre, second and kilogram. Dimensional analysis compares types of quantities; independent random uncertainties combine in quadrature rather than as signed errors.',[
 f('convert','Convert units using cancelling ratios','Decimal arithmetic; Metric prefixes','A larger unit means fewer units for the same amount.',n=>num(`A sensor logs ${150*n} centimetres. Convert to metres.`,1.5*n,'Use 1 m = 100 cm.',`${150*n} cm × (1 m/100 cm) = ${1.5*n} m.`,'The cm labels cancel and leave m.','Multiplying by 100 converts metres to centimetres, not the reverse.')),
 f('dimensions','Check dimensions of a proposed formula','Multiply units; Speed and acceleration','Equal numerical values do not repair incompatible units.',n=>choose(`A cart travels ${n+1} m in 2 s. Which unit describes its average speed?`,['m/s','m·s','m/s²'],0,'Speed is distance divided by elapsed time.','m/s² describes acceleration; m·s does not describe speed.')),
 f('precision','Round a reported measurement appropriately','Decimal place value; Rounding','Extra calculator digits are not extra measurement precision.',n=>num(`A length is ${n}.247 cm. Round to the nearest 0.01 cm.`,n+.25,'Keep two decimal places; the third decimal digit is 7.',`${n}.247 rounds to ${n}.25 cm.`,'The next digit determines whether the retained digit increases.','Truncation to .24 is not rounding.')),
 f('uncertainty','Propagate independent uncertainty in a sum','Squares and square roots; Uncertainty meaning','Independent standard uncertainties add as variances.',n=>num(`Two independent length measurements have standard uncertainties ${.3*n} cm and ${.4*n} cm. Find the standard uncertainty of their sum in cm.`,.5*n,'Use σ_sum=√(σ₁²+σ₂²).',`σ=√(${fmt((.3*n)**2)}+${fmt((.4*n)**2)})=${fmt(.5*n)} cm.`,'For independent random errors the variances add.','Adding uncertainties linearly gives a worst-case bound, a different requested quantity.'))
]);
bank('physics-vectors-and-motion','Displacement is change in position, while distance totals path length. Velocity is displacement per time and acceleration is velocity change per time. The constant-acceleration formulas here require acceleration to stay fixed over the interval.',[
 f('displacement','Distinguish distance and displacement','Signed coordinates; Subtraction','A return trip can have positive distance and zero displacement.',n=>num(`A walker travels ${3*n} m east then ${n} m west. Taking east as positive, find displacement in m.`,2*n,'Add the signed changes in position.',`${3*n}+(${-n})=${2*n} m.`,'Opposite directions have opposite signs.','Adding both lengths gives distance travelled, not displacement.')),
 f('velocity','Calculate average velocity','Signed displacement; Time units','Average speed uses distance; average velocity uses displacement.',n=>num(`A cart moves from x=${n} m to x=${5*n} m in 2 s. Find average velocity in m/s.`,2*n,'Divide position change by elapsed time.',`v_avg=(${5*n}−${n})/2=${2*n} m/s.`,'Average velocity measures net motion over the interval.','Using final position alone assumes the initial position is zero.')),
 f('acceleration','Apply constant acceleration to velocity','Rates; Signed arithmetic','Negative acceleration need not imply negative velocity.',n=>num(`A cart starts at 2 m/s and accelerates at ${n} m/s² for 3 s. Find final velocity.`,2+3*n,'Use v=v₀+at.',`v=2+${n}×3=${2+3*n} m/s.`,'Constant acceleration changes velocity by the same amount each second.','Multiplying acceleration by time gives the change, not the final velocity.')),
 f('position','Calculate position under constant acceleration','Squares; Velocity and acceleration','Displacement includes the initial velocity term.',n=>num(`A cart starts at x=0 with v₀=2 m/s, a=2 m/s² constant. Find its position after ${n} s.`,2*n+n*n,'Use x=x₀+v₀t+at²/2.',`x=0+2×${n}+2×${n}²/2=${2*n+n*n} m.`,'The average velocity grows linearly, giving the one-half factor.','v_final×t overestimates displacement for increasing speed.'))
]);
bank('physics-forces-and-free-bodies','A free-body diagram shows forces acting on one chosen object. Net force is their vector sum and equals mass times acceleration in an inertial frame. Weight is gravitational force, normal force is contact perpendicular to a surface, and friction opposes relative sliding.',[
 f('net-force','Combine opposing forces before applying Newton’s law','Signed arithmetic; Acceleration','Force and velocity point in different directions in some motions.',n=>num(`A ${n+1} kg cart has 12 N rightward and 4 N leftward forces. Neglect other horizontal forces. Find rightward acceleration in m/s².`,8/(n+1),'Net force is 12−4=8 N; use a=F_net/m.',`a=8/${n+1}=${fmt(8/(n+1))} m/s².`,'Acceleration responds to net force rather than to either force alone.','Using 12 N ignores the opposing force.')),
 f('weight','Distinguish mass, weight and normal force','Multiply quantities; Force units','Mass in kg differs from weight in N.',n=>num(`A ${n+2} kg object rests on a horizontal table. No other vertical force acts. Use g=10 m/s². Find normal-force magnitude in N.`,10*(n+2),'Vertical acceleration is zero, so normal force balances weight mg.',`N=mg=${n+2}×10=${10*(n+2)} N.`,'Vertical equilibrium requires the two forces to cancel.','Normal force need not equal mg when additional vertical forces or acceleration exist.')),
 f('friction','Use a kinetic-friction model','Normal force; Coefficients','Static friction adjusts up to a maximum; kinetic friction uses its specified model.',n=>num(`A box slides on a horizontal floor with normal force ${20*n} N and kinetic coefficient 0.25. Find friction magnitude in N.`,5*n,'Use f_k=μ_k N.',`f_k=0.25×${20*n}=${5*n} N.`,'The stated model applies to sliding contact.','Multiplying the coefficient by mass alone has the wrong force units.')),
 f('pairs','Identify a Newton’s-third-law pair','Identify chosen object; Force diagrams','Action and reaction act on different objects and do not cancel on one free-body diagram.',n=>choose(`A hand pushes box ${n} to the right. What is the paired force?`,['The floor’s upward force on the box.','The box’s leftward force on the hand.','The box’s weight.'],1,'Each interaction has equal and opposite forces on its two participants.','Weight and normal force are separate interactions, even when equal in equilibrium.'))
]);
bank('physics-work-and-energy','Work transfers energy by a force along a displacement. Kinetic energy depends on speed squared; gravitational potential changes by mgΔh near Earth. Mechanical energy is conserved only when the included system has no unaccounted energy transfers.',[
 f('work','Calculate work by a constant aligned force','Force; Displacement','A force perpendicular to displacement does zero work.',n=>num(`A constant ${5*n} N force acts parallel to a cart’s 3 m displacement. Find work in J.`,15*n,'Use W=Fd cos θ with θ=0.',`W=${5*n}×3×1=${15*n} J.`,'Only the force component along displacement transfers energy this way.','Adding force and distance combines incompatible units.')),
 f('kinetic','Calculate kinetic energy and speed changes','Squares; Mass','Doubling speed quadruples kinetic energy.',n=>num(`A 2 kg cart moves at ${n+1} m/s. Find kinetic energy in J.`,(n+1)**2,'Use K=mv²/2.',`K=2×${n+1}²/2=${(n+1)**2} J.`,'Kinetic energy is quadratic in speed.','Using mv gives momentum, not energy.')),
 f('potential','Find gravitational potential-energy change','Weight; Height change','Only the height difference matters for a potential-energy change.',n=>num(`A ${n+1} kg load rises 3 m. Use g=10 m/s². Find ΔU in J.`,30*(n+1),'Use ΔU=mgΔh.',`ΔU=${n+1}×10×3=${30*(n+1)} J.`,'Near Earth a fixed gravitational force acts through the height change.','Using absolute altitude rather than height change adds an arbitrary reference.')),
 f('conservation','Account for losses in an energy balance','Kinetic energy; Energy transfer','Friction changes mechanical energy while total energy is still conserved.',n=>num(`A cart starts with ${30*n} J mechanical energy and transfers ${5*n} J to thermal energy before reaching a point with 10 J potential energy. Find kinetic energy there.`,25*n-10,'Initial mechanical energy minus thermal transfer equals final K+U.',`K=${30*n}−${5*n}−10=${25*n-10} J.`,'All stated energy destinations must appear in the balance.','Ignoring thermal transfer treats a dissipative process as lossless.'))
]);
bank('physics-momentum-and-collisions','Momentum is mass times velocity with direction. Total momentum stays constant when external impulse is negligible. Impulse is force integrated over time; an inelastic collision can conserve momentum while reducing kinetic energy.',[
 f('momentum','Calculate signed momentum','Mass; Signed velocity','Momentum carries direction and uses velocity, not speed alone.',n=>num(`A 3 kg cart travels left at ${n+1} m/s. Take right positive. Find momentum in kg·m/s.`,-3*(n+1),'Use p=mv with negative leftward velocity.',`p=3×(${-n-1})=${-3*(n+1)} kg·m/s.`,'The sign preserves the direction of motion.','A positive value would describe rightward momentum.')),
 f('impulse','Connect impulse to velocity change','Newton’s second law; Time interval','Impulse changes momentum, not automatically final momentum.',n=>num(`A 2 kg cart initially at rest receives a constant ${4*n} N force for 0.5 s. Find final velocity in m/s.`,n,'Use J=FΔt=mΔv.',`J=${4*n}×0.5=${2*n}; v=J/2=${n} m/s.`,'Integrating force over time gives momentum change.','Force alone does not give a velocity without mass and time.')),
 f('inelastic','Solve a sticking collision','Signed momentum; Mass sum','The joined mass belongs in the final momentum.',n=>num(`A 2 kg cart at ${3*n} m/s hits a stationary 1 kg cart and they stick. External impulse is negligible. Find final velocity.`,2*n,'Conserve total momentum: 2v₁+1v₂=(2+1)v_f.',`v_f=(2×${3*n}+0)/3=${2*n} m/s.`,'Both carts share one final velocity.','Conserving kinetic energy is not valid for this sticking collision.')),
 f('elastic','Use an equal-mass elastic collision model','Momentum; Kinetic energy','Energy conservation alone does not specify directions.',n=>num(`Two equal-mass carts collide head-on elastically in one dimension. One initially has velocity ${n+2} m/s; the other is at rest. Find the second cart’s final velocity.`,n+2,'For an equal-mass elastic collision the velocities exchange.',`The second cart takes ${n+2} m/s and the first becomes stationary.`,'Simultaneous momentum and kinetic-energy conservation produce velocity exchange.','The carts sharing one velocity would describe a sticking collision.'))
]);
bank('physics-rotation-and-torque','Torque measures a force’s turning effect and uses the perpendicular lever arm. Moment of inertia describes how mass distribution resists angular acceleration. Angular quantities here use radians and fixed-axis rotation.',[
 f('torque','Calculate perpendicular torque','Force; Length; Angle meaning','The lever arm is perpendicular distance to the force’s line of action.',n=>num(`A ${10*n} N force acts perpendicular to a 0.3 m wrench. Find torque magnitude in N·m.`,3*n,'Use τ=rF for a perpendicular force.',`τ=0.3×${10*n}=${3*n} N·m.`,'The perpendicular force produces maximal turning effect at this radius.','A force along the handle would give zero torque.')),
 f('inertia','Compute a point-mass moment of inertia','Squares; Mass distribution','Mass farther from the axis contributes with distance squared.',n=>num(`A point mass of ${n+1} kg is 2 m from a fixed axis. Find moment of inertia in kg·m².`,4*(n+1),'Use I=mr² for a point mass.',`I=${n+1}×2²=${4*(n+1)} kg·m².`,'Rotational response depends on both mass and its distance from the axis.','mr has the wrong distance dependence and units.')),
 f('angular-acceleration','Apply τ=Iα','Net torque; Moment of inertia','Use net torque, and moment of inertia rather than mass alone.',n=>num(`A fixed-axis rotor has I=2 kg·m² and net torque ${6*n} N·m. Find angular acceleration in rad/s².`,3*n,'Use α=τ_net/I.',`α=${6*n}/2=${3*n} rad/s².`,'This is Newton’s second law for the specified fixed-axis model.','Dividing by radius rather than inertia does not give angular acceleration.')),
 f('rotational-energy','Account for rotational kinetic energy','Angular speed; Squares','Rotational and translational kinetic energies may both be present.',n=>num(`A rotor has I=4 kg·m² and angular speed ${n} rad/s. Find its rotational kinetic energy in J.`,2*n*n,'Use K_rot=Iω²/2.',`K=4×${n}²/2=${2*n*n} J.`,'Each mass element moves faster when angular speed increases.','Iω is angular momentum, not energy.'))
]);
bank('physics-oscillations-and-waves','Frequency counts cycles per second; period is time per cycle. Wave speed is frequency times wavelength. For an ideal spring-mass oscillator, restoring force is −kx and angular frequency is sqrt(k/m). These formulas assume small, linear oscillations.',[
 f('period','Convert frequency and period','Reciprocal; Seconds','Frequency and period are reciprocal quantities.',n=>num(`An oscillator completes ${n+1} cycles per second. Find its period in s.`,1/(n+1),'Use T=1/f.',`T=1/${n+1}=${fmt(1/(n+1))} s.`,'Each cycle occupies the reciprocal of the cycles per second.','Multiplying by frequency confuses cycles with time.')),
 f('speed','Relate wavelength, frequency and speed','Rates; Length units','Higher frequency does not imply higher speed in a fixed nondispersive medium.',n=>num(`A wave has frequency ${5*n} Hz and wavelength 2 m. Find speed in m/s.`,10*n,'Use v=fλ.',`v=${5*n}×2=${10*n} m/s.`,'A full wavelength advances in one period.','Dividing frequency by wavelength gives the wrong dimensions.')),
 f('spring','Calculate a spring restoring force','Signed displacement; Force','The minus sign directs the restoring force toward equilibrium.',n=>num(`An ideal spring has k=20 N/m and displacement x=${n/10} m to the right. Find signed force, with right positive.`,-2*n,'Use F=−kx.',`F=−20×${n/10}=${-2*n} N.`,'A restoring force opposes the displacement from equilibrium.','A positive sign would push the spring farther from equilibrium.')),
 f('resonance','Calculate natural frequency and interpret resonance','Square roots; Frequency and angular frequency','Angular frequency differs from frequency by 2π.',n=>num(`A spring-mass system has m=1 kg and k=${4*n*n} N/m. Find its natural angular frequency in rad/s.`,2*n,'Use ω₀=√(k/m).',`ω₀=√(${4*n*n}/1)=${2*n} rad/s.`,'The linear restoring equation determines this natural rate of oscillation.','Dividing by 2π would give cycles per second, not angular frequency.'))
]);
bank('physics-fluids-and-flow','Density is mass per volume; pressure is force per area. Hydrostatic pressure increases with depth in a stationary fluid. Continuity for steady incompressible flow conserves volume flow rate; Bernoulli additionally assumes negligible viscosity along a streamline.',[
 f('density','Calculate density with volume units','Division; Cubic units','Density differs from mass and depends on volume.',n=>num(`A sample has mass ${2*n} kg and volume 0.002 m³. Find density in kg/m³.`,1000*n,'Use ρ=m/V.',`ρ=${2*n}/0.002=${1000*n} kg/m³.`,'Density measures mass per unit volume.','Dividing volume by mass gives the reciprocal density.')),
 f('hydrostatic','Find pressure change with depth','Density; Gravity; Length','ρgh gives pressure relative to the surface, not automatically absolute pressure.',n=>num(`Water has ρ=1000 kg/m³. Use g=10 m/s². Find the pressure increase at depth ${n} m in Pa.`,10000*n,'Use Δp=ρgh.',`Δp=1000×10×${n}=${10000*n} Pa.`,'Deeper fluid supports more overlying fluid weight.','Surface atmospheric pressure must be added if absolute pressure is requested.')),
 f('continuity','Apply incompressible flow continuity','Area; Flow speed','Narrower area increases speed for fixed volume flow.',n=>num(`Steady incompressible water flows at ${n} m/s through area 0.04 m² into area 0.01 m². Find downstream speed.`,4*n,'Use A₁v₁=A₂v₂.',`v₂=0.04×${n}/0.01=${4*n} m/s.`,'The same volume must enter and leave each second.','Scaling speed down with area violates volume conservation.')),
 f('buoyancy','Calculate buoyant force from displaced fluid','Density; Volume; Weight','Buoyancy depends on displaced fluid, not object mass directly.',n=>num(`An immersed object displaces ${n/1000} m³ of water. Use ρ=1000 kg/m³ and g=10 m/s². Find buoyant force in N.`,10*n,'Use F_b=ρ_fluid g V_displaced.',`F_b=1000×10×${n/1000}=${10*n} N.`,'Pressure variation creates a net upward force equal to displaced fluid weight.','Using object density answers a different weight calculation.'))
]);
bank('physics-heat-and-thermodynamics','Temperature describes thermal state; heat is energy transferred because of a temperature difference. Specific heat relates energy to temperature change without a phase change. Use ΔU=Q−W, with Q positive into the system and W positive for work done by the system.',[
 f('sensible-heat','Calculate heating without a phase change','Mass; Temperature differences','Heat and temperature have different units.',n=>num(`Heat ${n} kg of water by 5 K with c=4200 J/(kg·K), without phase change or losses. Find energy input in J.`,21000*n,'Use Q=mcΔT.',`Q=${n}×4200×5=${21000*n} J.`,'Specific heat gives energy per kilogram per degree of temperature change.','Using final temperature rather than its change adds the initial-state energy incorrectly.')),
 f('first-law','Apply the energy balance with explicit signs','Energy; Work','Work done by the system removes internal energy under this convention.',n=>num(`A gas absorbs ${100*n} J heat and does ${30*n} J work. Find ΔU in J using ΔU=Q−W.`,70*n,'Subtract outward work from inward heat.',`ΔU=${100*n}−${30*n}=${70*n} J.`,'Energy entering and leaving must have opposite balance signs.','Adding outward work treats it as energy entering.')),
 f('ideal-gas','Use absolute temperature in a gas law','Kelvin temperature; Division','Ideal-gas ratios require kelvin, not Celsius.',n=>num(`A sealed ideal gas at fixed volume and amount has pressure 100 kPa at 300 K. Find pressure at ${300+30*n} K in kPa.`,100+10*n,'At fixed V and amount, P/T is constant.',`P₂=100×${300+30*n}/300=${100+10*n} kPa.`,'PV=nRT makes pressure proportional to absolute temperature here.','Using Celsius ratios does not measure thermal energy correctly.')),
 f('efficiency','Calculate heat-engine efficiency','Energy fractions; Percentages','No engine can convert all absorbed heat to work in a cyclic process with finite reservoirs.',n=>num(`A cyclic engine takes in ${200*n} J and rejects ${120*n} J. Find efficiency as a decimal.`,.4,'Net work is Q_in−Q_out; divide by Q_in.',`η=(${200*n}−${120*n})/${200*n}=0.4.`,'Over one full cycle internal energy returns to its starting value.','Q_out/Q_in gives the rejected fraction, not efficiency.'))
]);
bank('physics-electric-fields-and-potential','Electric field is force per positive test charge; potential difference is energy change per charge. Signs matter. Coulomb’s law here describes stationary point charges; k=9×10^9 N·m²/C² is the stated approximation.',[
 f('coulomb','Calculate point-charge force magnitude','Powers of ten; Inverse-square relationship','Opposite signs attract, but force magnitude is nonnegative.',n=>num(`Two point charges have magnitudes 1 μC and ${n} μC, separated by 0.1 m in vacuum. Use k=9×10^9. Find force magnitude in N.`,.9*n,'Convert μC to 10^−6 C; use F=k|q₁q₂|/r².',`F=9×10^9×10^−6×${n}×10^−6/0.1²=${fmt(.9*n)} N.`,'Each charge contributes and the separation enters squared.','Using μC as C overstates the result by 10^12.')),
 f('field','Calculate force from a signed field','Charge units; Vector signs','Field direction is defined for a positive test charge.',n=>num(`E=${100*n} N/C to the right. A charge is −0.02 C. Taking right positive, find its electric force in N.`,-2*n,'Use F=qE with the signed charge.',`F=−0.02×${100*n}=${-2*n} N.`,'A negative charge feels force opposite the field.','Taking the magnitude of charge too early loses direction.')),
 f('potential-energy','Relate potential and energy changes','Multiply charge by voltage; Energy units','Potential is per charge; it is not itself energy.',n=>num(`A positive 0.5 C charge moves through a potential increase of ${4*n} V. Find its electric potential-energy change in J.`,2*n,'Use ΔU=qΔV.',`ΔU=0.5×${4*n}=${2*n} J.`,'Positive charges gain electric potential energy toward higher potential.','The electric field’s work is −ΔU, a different requested quantity.')),
 f('uniform-field','Use potential difference in a uniform field','Field direction; Voltage and distance','Potential decreases along the field direction.',n=>num(`A uniform field is 20 V/m to the right. Move ${n/10} m right. Find V_final−V_initial in V.`,-2*n,'Use ΔV=−EΔx.',`ΔV=−20×${n/10}=${-2*n} V.`,'The field points toward decreasing potential.','The magnitude EΔx alone omits the requested signed change.'))
]);
bank('physics-circuits-and-magnetism','Current is charge flow per time; voltage is energy per charge. Ohm’s law assumes an ohmic resistor. Series currents match; parallel voltages match. Magnetic force on a moving charge depends on velocity perpendicular to the field.',[
 f('ohm','Calculate an ohmic current','Voltage; Resistance; Division','Voltage and current are different quantities.',n=>num(`An ohmic resistor of 4 Ω has ${4*n} V across it. Find current in A.`,n,'Use I=V/R.',`I=${4*n}/4=${n} A.`,'Resistance relates voltage to current for the stated ohmic model.','Multiplying voltage and resistance does not produce current.')),
 f('networks','Combine series and parallel resistors','Fractions; Ohm’s law','Parallel equivalent resistance is smaller than each positive branch resistance.',n=>num(`Two resistors of ${2*n} Ω each are connected in parallel. Find equivalent resistance in Ω.`,n,'Use 1/R_eq=1/R₁+1/R₂.',`1/R_eq=2/${2*n}=1/${n}; R_eq=${n} Ω.`,'Parallel branches provide additional current paths at the same voltage.','Adding the two resistances would describe series connection.')),
 f('power','Calculate electrical energy usage','Work; Power; Time','Watts describe rate; joules describe total energy.',n=>num(`A device draws 2 A from ${3*n} V for 10 s. Find electrical energy supplied in J.`,60*n,'Use P=VI, then E=Pt.',`P=${3*n}×2=${6*n} W; E=${6*n}×10=${60*n} J.`,'Power multiplied by duration accumulates transferred energy.','VI alone reports watts, not the requested joules.')),
 f('magnetic-force','Calculate a magnetic-force magnitude','Charge; Speed; Perpendicular vectors','Magnetic force is zero for motion parallel to the field.',n=>num(`A charge of 0.2 C moves at ${5*n} m/s perpendicular to a 3 T magnetic field. Find force magnitude in N.`,3*n,'Use F=|q|vB sinθ with θ=90°.',`F=0.2×${5*n}×3=${3*n} N.`,'Only perpendicular motion contributes to the magnetic force.','For parallel motion sinθ=0; do not use this maximum-force formula there.'))
]);
bank('physics-light-and-optics','The refractive index is vacuum light speed divided by medium speed. Refraction obeys Snell’s law. Thin-lens equations here use positive focal length for a converging lens and positive real-object distance; positive image distance denotes a real image on the far side.',[
 f('index','Calculate light speed from refractive index','Ratios; Speed units','Frequency stays fixed at a stationary boundary while wavelength changes.',n=>num(`A transparent medium has refractive index ${1+n/10}. Use c=3×10^8 m/s. Find light speed in m/s.`,3e8/(1+n/10),'Use v=c/n_index.',`v=3×10^8/${fmt(1+n/10)}=${fmt(3e8/(1+n/10))} m/s.`,'Refractive index compares vacuum speed to medium speed.','Multiplying by refractive index would predict a speed larger than c.')),
 f('snell','Apply Snell’s law to a sine value','Trigonometric sine; Ratios','Angles are measured from the normal to the surface.',n=>num(`Light enters n₂=1.5 from n₁=1. Its incident angle has sinθ₁=${n/10}. Find sinθ₂.`,n/15,'Use n₁sinθ₁=n₂sinθ₂.',`sinθ₂=(1/1.5)×${n/10}=${fmt(n/15)}.`,'Matching wave fronts at the boundary gives Snell’s law.','Using the angle from the surface swaps sine and cosine.')),
 f('lens','Calculate a thin-lens image distance','Reciprocals; Sign convention','The image distance is not generally object distance minus focal length.',n=>num(`A thin converging lens has f=10 cm and a real object at d_o=${20+5*n} cm. Find signed image distance in cm.`,10*(20+5*n)/(10+5*n),'Use 1/f=1/d_o+1/d_i.',`d_i=1/(1/10−1/${20+5*n})=${fmt(10*(20+5*n)/(10+5*n))} cm.`,'The stated real-object and converging-lens signs determine the image side.','Subtracting distances directly ignores the reciprocal relationship.')),
 f('magnification','Interpret signed lens magnification','Lens distances; Ratios','Negative magnification means inversion, not negative physical size.',n=>num(`A thin lens has d_o=${10*n} cm and real d_i=${5*n} cm under the stated sign convention. Find signed magnification.`,-.5,'Use m=−d_i/d_o.',`m=−${5*n}/${10*n}=−0.5.`,'The image is inverted and half the object’s height.','A positive value would imply an upright image under this convention.'))
]);
bank('physics-relativity-and-modern-physics','Special relativity compares inertial observers moving at constant relative velocity. Proper time is measured by a clock present at both events; γ=1/sqrt(1−v²/c²). Rest energy is mc² and is distinct from kinetic energy.',[
 f('lorentz','Calculate the Lorentz factor','Squares; Square roots; Speed fractions','Use speed divided by c, not raw speed in γ.',n=>{const b=n/10;return num(`An observer moves at v=${b}c. Find γ.`,1/Math.sqrt(1-b*b),'Use γ=1/√(1−(v/c)²).',`γ=1/√(1−${fmt(b*b)})=${fmt(1/Math.sqrt(1-b*b))}.`,'The speed ratio is dimensionless and below one.','Using √(1−β²) gives the reciprocal Lorentz factor.');}),
 f('time','Apply time dilation to proper time','Lorentz factor; Event definition','Proper time is the interval on the clock present at both events.',n=>num(`A moving clock measures proper time ${n} s. Its speed is 0.6c relative to the lab. Find lab time in s.`,1.25*n,'At β=0.6, γ=1.25; use Δt=γΔτ.',`Δt=1.25×${n}=${1.25*n} s.`,'The lab observes the moving clock accumulate less time between these events.','Dividing by γ gives the wrong observer interval.')),
 f('length','Apply length contraction along motion','Rest-frame length; γ','Only the length component parallel to motion contracts.',n=>num(`A rod has rest length ${4*n} m parallel to its velocity 0.6c. Find its length measured simultaneously in the lab in m.`,3.2*n,'Use L=L₀/γ with γ=1.25.',`L=${4*n}/1.25=${fmt(3.2*n)} m.`,'Lab-simultaneous endpoints define the lab length.','Multiplying by γ lengthens the rod and reverses the stated relationship.')),
 f('rest-energy','Distinguish rest energy from kinetic energy','Mass; Powers of ten','A body has rest energy even when its kinetic energy is zero.',n=>num(`A stationary body has mass ${n/1000} kg. Use c=3×10^8 m/s. Find rest energy in J.`,9e13*n,'Use E₀=mc².',`E₀=${n/1000}×(3×10^8)²=${fmt(9e13*n)} J.`,'Rest energy measures the energy equivalent of invariant mass.','mc uses the wrong power of speed and wrong energy dimensions.'))
]);
bank('physics-quantum-models','A photon has energy hf; a matter wave has wavelength h/p. Energy levels can be discrete in a bound system. The photoelectric model uses one photon to remove one electron, with maximum kinetic energy hf minus the material work function.',[
 f('photon','Convert photon frequency to energy','Powers of ten; Frequency','Photons at higher frequency have higher energy per photon, irrespective of beam intensity.',n=>num(`A photon has frequency ${n}×10^14 Hz. Use h=6.626×10^−34 J·s. Find energy in J.`,6.626e-20*n,'Use E=hf.',`E=6.626×10^−34×${n}×10^14=${fmt(6.626e-20*n)} J.`,'Planck’s relation connects photon frequency to its energy.','Intensity counts energy flow and does not set single-photon energy by itself.')),
 f('matter-wave','Calculate a de Broglie wavelength','Momentum; Division','Wavelength is inversely proportional to momentum.',n=>num(`A particle has momentum ${n}×10^−24 kg·m/s. Use h=6.626×10^−34 J·s. Find its de Broglie wavelength in m.`,6.626e-10/n,'Use λ=h/p.',`λ=6.626×10^−34/(${n}×10^−24)=${fmt(6.626e-10/n)} m.`,'The momentum determines the spatial phase variation of the matter wave.','Multiplying by momentum reverses the dependence and fails the units.')),
 f('photoelectric','Calculate maximum photoelectron kinetic energy','Energy units; Subtraction','Increasing intensity below threshold does not eject electrons in this single-photon model.',n=>num(`Each photon carries ${n+3} eV; the work function is 2 eV. Assume the single-photon photoelectric model. Find maximum electron kinetic energy in eV.`,n+1,'Use K_max=E_photon−φ.',`K_max=${n+3}−2=${n+1} eV.`,'Removing the electron costs the work-function energy.','Adding the work function creates energy rather than paying the removal cost.')),
 f('transitions','Calculate energy emitted in a level transition','Signed energy; Energy differences','Photon energy is positive for a downward transition.',n=>num(`An atom falls from an energy level ${n+4} eV above its ground state to one 1 eV above ground. Find emitted photon energy in eV.`,n+3,'Use E_photon=E_initial−E_final.',`E_photon=${n+4}−1=${n+3} eV.`,'The lost atomic energy is carried by the emitted photon.','Subtracting in the reverse order gives the atom’s signed change, not photon energy.'))
]);
bank('physics-statistical-physics','Microstates specify detailed configurations; macrostates describe bulk properties. Boltzmann entropy is S=k_B lnΩ for equally likely microstates. Thermal occupation ratios use exp(−ΔE/k_BT) for the nondegenerate levels and equilibrium assumptions stated here.',[
 f('count','Count distinct binary microstates','Powers; Independent choices','Different arrangements count separately even with the same total.',n=>num(`There are ${n+2} distinguishable independent two-state units, each labelled 0 or 1. How many microstates exist?`,2**(n+2),'Multiply two choices for each labelled unit.',`Ω=2^${n+2}=${2**(n+2)}.`,'Each unit can choose independently and position labels distinguish arrangements.','n+3 counts possible numbers of ones, which are macrostates here.')),
 f('entropy','Calculate entropy in units of Boltzmann’s constant','Natural logarithm; Microstate count','Entropy is logarithmic in multiplicity.',n=>num(`An equally likely macrostate has Ω=${2**n}. Find S/k_B.`,n*Math.log(2),'Use S/k_B=lnΩ.',`ln(${2**n})=${n}ln2=${fmt(n*Math.log(2))}.`,'A logarithm makes independent multiplicative counts into additive entropies.','Ω itself is a count, not S/k_B.')),
 f('boltzmann','Use a thermal population ratio','Exponential decay; Energy and temperature','The stated nondegenerate ratio excludes degeneracy factors.',n=>num(`Two nondegenerate levels in thermal equilibrium differ by ΔE=${n/2}k_BT. Find N_high/N_low.`,Math.exp(-n/2),'Use the Boltzmann ratio exp(−ΔE/k_BT).',`N_high/N_low=exp(${-n/2})=${fmt(Math.exp(-n/2))}.`,'Higher energy states have lower thermal weight at positive temperature.','A positive exponent would favour higher energies without bound.')),
 f('averages','Calculate an ensemble mean energy','Weighted averages; Probabilities','Mean energy need not equal any individual measured energy.',n=>num(`A two-level ensemble has energy 0 with probability 0.75 and ${4*n} J with probability 0.25. Find mean energy in J.`,n,'Weight each energy by its probability.',`⟨E⟩=0×0.75+${4*n}×0.25=${n} J.`,'The ensemble average combines many repeated measurements.','Adding level energies without probability weights is not an average.'))
]);
bank('physics-computational-physics','A numerical model approximates continuous evolution with finite steps. Euler’s method uses the current slope; it generally has discretization error. Compare against an analytic result or a smaller-step calculation, and distinguish integration error from model assumptions.',[
 f('euler','Take a forward Euler step','Rates; Multiplication; Initial values','Forward Euler uses the current state and slope.',n=>num(`For dx/dt=−2x, x(0)=${n+1}, take one forward Euler step of h=0.1 s. Find x after the step.`,.8*(n+1),'Use x_new=x_old+h(−2x_old).',`x_new=${n+1}−0.2×${n+1}=${fmt(.8*(n+1))}.`,'Forward Euler approximates the slope as constant during one step.','Using the unknown new x in the slope is an implicit method.')),
 f('steps','Iterate a simple numerical update','Euler step; Powers','Two steps require updating the state before computing the second slope.',n=>num(`Use x_new=0.9x_old with x₀=${n+1}. Find x₂ after two updates.`,.81*(n+1),'Apply the update twice.',`x₁=0.9×${n+1}; x₂=0.9²×${n+1}=${fmt(.81*(n+1))}.`,'The next update acts on the new state.','Subtracting 0.1x₀ twice reuses the old slope.')),
 f('error','Compare a numerical prediction with a reference','Absolute value; Fractions','Relative error must specify a nonzero reference value.',n=>num(`A benchmark gives ${10*n} units; a simulation gives ${9*n} units. Find absolute relative error as a decimal.`,.1,'Use |numerical−reference|/|reference|.',`Error=|${9*n}−${10*n}|/${10*n}=0.1.`,'Normalizing by the benchmark gives a scale-independent comparison.','Signed error would be negative; the requested error is absolute.')),
 f('convergence','Check first-order step-size convergence','Numerical error; Ratios','Smaller steps improve discretization only for an appropriate stable method.',n=>rubric(`A stable simulation has error ${.08*n} at step h and ${.04*n} at h/2 against a trusted solution. Explain whether this is consistent with first-order convergence, and name one remaining validation check.`,['Compute error ratio 2','Connect halved step to halved leading error','State two data points do not prove convergence order','Name conservation, units, model assumptions or another refinement check'],[[`Error ratio=${fmt(.08*n)}/${fmt(.04*n)}=2.`,'First-order error is proportional to h in the convergent regime.'],['The observations are consistent with first-order behaviour.','A further refinement should establish whether the trend continues.'],['Check a conserved quantity and the intended physical assumptions.','A converging algorithm can still solve an incorrect model.']],['Compare errors rather than the solution values.','Separate algorithm accuracy from model validity.'],'Two similar plots do not establish that either result is physically correct.'))
]);
bank('quantum-complex-numbers','Complex numbers a+bi have i²=−1. The conjugate changes i to −i; modulus squared is a²+b² and gives an amplitude’s probability contribution. A phase is an angle in exp(iθ)=cosθ+i sinθ. Use basic signed arithmetic, squares and right-triangle lengths.',[
 f('arithmetic','Multiply complex amplitudes','Signed arithmetic; Distributive multiplication','i²=−1, so multiplying imaginary parts creates a real contribution.',n=>txt(`Multiply (${n}+i)(1−i). Enter a+bi or a-bi without spaces.`,[`${n+1}${1-n>=0?'+':''}${1-n}i`,...(n===1?['2']:[])],'Distribute the two factors and replace i² by −1.',`${n}−${n}i+i−i²=${n+1}+(${1-n})i.`,'The imaginary unit squares to minus one.','Keeping i² as positive one changes the real part.')),
 f('modulus','Find squared modulus and amplitude weight','Squares; Complex conjugate','Probability uses squared modulus, not just the real part.',n=>num(`For amplitude a=${n}+2i, find |a|².`,n*n+4,'Use |a|²=a* a = real²+imaginary².',`|${n}+2i|²=${n}²+2²=${n*n+4}.`,'Multiplication by the conjugate cancels imaginary cross terms.','This unnormalized amplitude weight is not itself a valid probability until the full state is normalized.')),
 f('conjugate','Apply conjugation in a product','Complex arithmetic; Sign of i','The conjugate changes the imaginary sign, not the real sign.',n=>txt(`Find the conjugate of ${n}−3i. Enter a+bi.`,[`${n}+3i`,`${n} + 3i`],'Keep the real part and reverse the imaginary part.','The conjugate is '+n+'+3i.','Conjugation reflects the complex plane across its real axis.','Negating the entire number gives −n+3i, a different operation.')),
 f('phase','Evaluate a relative-phase interference amplitude','Euler formula; Complex modulus','A global phase cancels in probabilities, but relative phases can change interference.',n=>{const theta=n*Math.PI/6;return num(`Two equal path amplitudes combine as A=(1+exp(iθ))/2 with θ=${n}π/6. Find |A|².`,(1+Math.cos(theta))/2,'Expand with exp(iθ)=cosθ+i sinθ.',`|A|²=((1+cosθ)²+sin²θ)/4=(1+cosθ)/2=${fmt((1+Math.cos(theta))/2)}.`,'The cross term depends on the relative phase between paths.','Adding separate path probabilities ignores interference.');})
]);
bank('quantum-probability-and-waves','Probabilities sum to one; quantum amplitudes are complex numbers whose squared magnitudes give probabilities in a chosen measurement basis. Indistinguishable coherent alternatives add amplitudes; distinguishable alternatives add probabilities. Frequency and wavelength describe phase oscillation, not event chance.',[
 f('normalization','Normalize outcome weights','Fractions; Squares','A raw amplitude vector must be normalized before interpreting weights.',n=>num(`Two outcomes have unnormalized real amplitudes 1 and ${n+1}. Find the normalized probability of the first.`,1/(1+(n+1)**2),'Square both amplitudes and divide the first weight by their sum.',`P₁=1/(1+${n+1}²)=${fmt(1/(1+(n+1)**2))}.`,'Normalization makes all outcome probabilities sum to one.','Dividing by the sum of amplitudes instead of squared amplitudes is not the Born rule.')),
 f('interference','Compute coherent interference','Add signed amplitudes; Squares','Alternatives that retain path information do not use the same coherent sum.',n=>num(`In an interference model, coherent amplitudes for one detector outcome are ${n/20} and −${n/40}. Find the probability of that outcome; other outcomes complete normalization.`,(n/40)**2,'Add amplitudes before taking the squared magnitude.',`A=${n/20}−${n/40}=${n/40}; P=A²=${fmt((n/40)**2)}.`,'The paths are stated to be coherent and indistinguishable at this outcome.','Adding amplitude squares removes the destructive interference.')),
 f('complement','Use mutually exclusive exhaustive outcomes','Probability sum; Subtraction','A complement formula requires the listed outcomes to exhaust possibilities.',n=>num(`A detector has two exhaustive outcomes A and B. P(A)=${n/10}. Find P(B).`,1-n/10,'Use P(A)+P(B)=1.',`P(B)=1−${n/10}=${fmt(1-n/10)}.`,'Exactly one of the two outcomes occurs on each trial.','A third unlisted possible outcome would invalidate this complement.')),
 f('counts','Predict expected counts without guaranteeing a run','Multiplication; Probability','An expected count need not be the count in any particular finite run.',n=>num(`An ideal repeated preparation gives detector probability 0.25. In ${40*n} independent trials, find the expected detector count.`,10*n,'Expected count = trials × event probability.',`${40*n}×0.25=${10*n}.`,'Linearity of expectation predicts the mean over repeated sets of trials.','An expected count is not a guarantee of exactly that many events.'))
]);
bank('quantum-wavefunctions-and-probability','A wavefunction ψ(x) is a complex position amplitude; |ψ(x)|² is probability density, so an interval probability is its integral. Normalize over the whole allowed domain. Density has inverse-length units and can exceed one without any interval probability exceeding one.',[
 f('constant','Normalize a constant wavefunction','Squares; Integration of a constant','The normalization constant is 1/√L, not 1/L.',n=>num(`ψ(x)=A real positive on 0≤x≤${n+1} m and zero elsewhere. Find A in m^(-1/2).`,1/Math.sqrt(n+1),'Set ∫|ψ|²dx=A²L=1.',`A=1/√${n+1}=${fmt(1/Math.sqrt(n+1))}.`,'Total position probability must equal one.','1/L normalizes density, not the wavefunction amplitude.')),
 f('interval','Integrate position probability over an interval','Fractions; Uniform density','The probability at an exact point of a continuous distribution is zero.',n=>num(`A particle has uniform density 1/${n+2} per metre over 0≤x≤${n+2} m. Find P(0≤x≤1 m).`,1/(n+2),'Integrate the constant density over the one-metre interval.',`P=(1/${n+2})×1=${fmt(1/(n+2))}.`,'Density must be multiplied by interval length to give probability.','The value of the density is not a point probability.')),
 f('nonuniform','Normalize and integrate a nonuniform density','Polynomial integrals; Probability','A high density near one location does not make all interval probabilities equal.',n=>{const L=n+1;return num(`On 0≤x≤${L} m, density is p(x)=3x²/${L**3}; it is zero elsewhere. Find P(0≤x≤${L/2} m).`,.125,'Integrate p(x); its cumulative probability is x³/L³.',`P=(${L/2})³/${L}³=1/8=0.125.`,'Integrating density accounts for the increasing weight with x.','Half the interval does not mean half the probability for a nonuniform density.');}),
 f('expectation','Calculate a position expectation','Integrate x times density; Units','The expectation is a mean and can differ from the most likely position.',n=>{const L=n+1;return num(`A normalized position density is p(x)=2x/${L*L} on 0≤x≤${L} m. Find ⟨x⟩ in m.`,2*L/3,'Use ⟨x⟩=∫x p(x)dx.',`⟨x⟩=(2/${L*L})∫₀^${L}x²dx=2×${L}/3=${fmt(2*L/3)} m.`,'Expectation weights every position by its density.','L/2 is the uniform-distribution mean, not this increasing-density mean.');})
]);
bank('quantum-superposition','Basis states |0⟩ and |1⟩ are orthogonal unit vectors. A normalized superposition α|0⟩+β|1⟩ has |α|²+|β|²=1. Relative phase affects measurements in other bases; multiplying the entire state by one unit-modulus phase leaves its predictions unchanged.',[
 f('weights','Compute probabilities in the defining basis','Complex modulus; Probability normalization','Coefficients are amplitudes, not probabilities.',n=>num(`A qubit is (|0⟩+${n+1}|1⟩)/√${1+(n+1)**2}. Find P(1) in the {|0⟩,|1⟩} basis.`,(n+1)**2/(1+(n+1)**2),'Square the normalized coefficient of |1⟩.',`P(1)=${(n+1)**2}/${1+(n+1)**2}=${fmt((n+1)**2/(1+(n+1)**2))}.`,'The Born rule takes the squared magnitude in the measurement basis.','Using (n+1)/normalizer gives an amplitude rather than a probability.')),
 f('phase','Measure a phase-dependent superposition in the X basis','Inner product; Euler formula','Equal Z-basis probabilities do not imply equal states.',n=>{const t=n*Math.PI/6;return num(`|ψ⟩=(|0⟩+exp(i${n}π/6)|1⟩)/√2. With |+⟩=(|0⟩+|1⟩)/√2, find P(+).`,(1+Math.cos(t))/2,'Take |⟨+|ψ⟩|²; overlap is (1+exp(iθ))/2.',`P(+)=(1+cos(${n}π/6))/2=${fmt((1+Math.cos(t))/2)}.`,'Changing basis combines amplitudes and reveals relative phase.','Using 1/2 regardless of phase confuses X and Z measurements.');}),
 f('global','Recognize physically equivalent global phases','Complex phase; Normalized vectors','A global phase differs from changing the sign of one component.',n=>choose(`For |ψ⟩=(|0⟩+|1⟩)/√2, which transformation preserves all measurement probabilities? Let θ=${n}π/7.`,['Multiply the entire vector by exp(iθ).','Multiply only the |1⟩ coefficient by exp(iθ).','Set the |1⟩ coefficient to zero.'],0,'A common unit-modulus factor cancels from every squared overlap.','A relative phase can change other-basis probabilities, and deleting a component changes the state.')),
 f('mixture','Distinguish coherent superposition from random preparation','Measurement basis; Classical probability','A mixture has no coherent cross term between its alternatives.',n=>num(`A preparation chooses |0⟩ with probability ${n/10} and |1⟩ otherwise. It is a classical mixture, not a coherent superposition. Find P(+) in the X basis.`,.5,'Each Z-basis state separately gives P(+)=1/2.',`P(+)=(${n/10})(1/2)+(1−${n/10})(1/2)=1/2.`,'Classically selected preparations combine outcome probabilities.','Adding the preparation amplitudes would insert coherence that the mixture does not contain.'))
]);
bank('quantum-measurement-outcomes','A projective measurement uses orthonormal eigenstates: outcome probability is squared overlap, and an ideal selective measurement leaves the corresponding eigenstate. Expectation is the probability-weighted mean; variance describes spread, rather than uncertainty about a fixed hidden answer.',[
 f('born','Apply the Born rule to a normalized state','Normalization; Complex magnitude','A coefficient squared is the probability only for the specified basis.',n=>num(`|ψ⟩=(√${n}|a⟩+√2|b⟩)/√${n+2}, with orthonormal |a⟩,|b⟩. Find P(a).`,n/(n+2),'Square the coefficient of the measured eigenstate |a⟩.',`P(a)=${n}/${n+2}=${fmt(n/(n+2))}.`,'Orthogonal outcomes have separate amplitude weights.','The probability is n/(n+2), not √n/√(n+2).')),
 f('repeat','Predict immediate repeated ideal measurement','Eigenstates; Ideal projective measurement','Repeatability assumes no intervening evolution or incompatible measurement.',n=>num(`An ideal Z-basis measurement of qubit ${n} produced 1. Immediately repeat it with no evolution. Find P(1).`,1,'The selective first measurement leaves state |1⟩.',`P(1)=|⟨1|1⟩|²=1.`,'The measured eigenstate is unchanged by the same projective measurement.','Reusing the original premeasurement probabilities ignores the selected outcome.')),
 f('mean','Calculate an observable expectation','Weighted mean; Eigenvalues','An expectation need not be an allowed single outcome.',n=>num(`An observable returns +${n} with probability 0.75 and −${n} with probability 0.25. Find its expectation.`,n/2,'Multiply each eigenvalue by its probability and add.',`⟨A⟩=${n}×0.75−${n}×0.25=${n/2}.`,'Expectation is the mean across identically prepared trials.','The most probable outcome +n is not the mean.')),
 f('variance','Calculate outcome variance','Expectation; Squares','Variance is ⟨A²⟩−⟨A⟩², not ⟨A²⟩ alone.',n=>num(`An observable yields +${n} and −${n}, each with probability 1/2. Find its variance.`,n*n,'The mean is zero and each squared outcome is n².',`Var(A)=⟨A²⟩−⟨A⟩²=${n*n}−0=${n*n}.`,'Opposite signed outcomes cancel in the mean but not in spread.','A zero mean does not imply zero variance.'))
]);
bank('quantum-uncertainty-relations','Standard deviations Δx and Δp quantify the spreads of position and momentum distributions in one preparation. Robertson’s inequality is ΔAΔB≥|⟨[A,B]⟩|/2, where [A,B]=AB−BA. For position and momentum this becomes ΔxΔp≥ℏ/2; it is a bound on spreads, not simply detector error.',[
 f('position-momentum','Calculate a minimum momentum spread','Division; Units; Standard deviation','The lower bound does not say every state attains equality.',n=>num(`Use units with ℏ=1. A state has Δx=${n/2}. Find the lower bound on Δp.`,1/n,'Use Δp≥ℏ/(2Δx).',`Δp≥1/(2×${n/2})=${fmt(1/n)}.`,'Canonical position and momentum obey [x,p]=iℏ.','The product bound is a minimum, not an equality for every state.')),
 f('check','Test a proposed uncertainty pair','Multiply spreads; ℏ convention','A pair below the bound cannot describe a valid quantum state under these assumptions.',n=>choose(`In units ℏ=1, proposed spreads are Δx=${n}, Δp=${.2/n}. Are they possible for canonical position and momentum?`,['Yes, because both are positive.','No: their product is 0.2, below 0.5.','Only if detector error is zero.'],1,'The proposed product violates ΔxΔp≥1/2.','Positivity alone is insufficient; the state’s spreads must satisfy the commutation bound.')),
 f('commutator','Use a supplied commutator expectation','Complex magnitude; Standard deviations','A zero expectation of a commutator can give a trivial bound without implying compatible observables.',n=>num(`For observables A,B, ⟨[A,B]⟩=${2*n}i in chosen units. Find Robertson’s lower bound on ΔAΔB.`,n,'Take half the modulus of the commutator expectation.',`|${2*n}i|/2=${n}.`,'The modulus removes the imaginary phase while retaining its magnitude.','Using the signed imaginary value would not produce a real spread bound.')),
 f('gaussian','Recognize the minimum-uncertainty Gaussian scaling','Gaussian width; Standard deviation','Changing a Gaussian’s position width changes its momentum width inversely.',n=>num(`A minimum-uncertainty Gaussian has Δx=${n+1} in units ℏ=1, with no position-momentum chirp. Find Δp.`,1/(2*(n+1)),'For the specified minimum-uncertainty state, use equality ΔxΔp=1/2.',`Δp=1/(2×${n+1})=${fmt(1/(2*(n+1)))}.`,'The stated unchirped Gaussian attains the canonical lower bound.','Equality would not be justified from Δx alone for an arbitrary state.'))
]);
bank('quantum-schrodinger-equation','Schrödinger evolution is iℏ∂ψ/∂t=Hψ. The Hamiltonian H is the energy operator; an eigenstate satisfies Hψ=Eψ. Energy eigenstates accumulate phase exp(−iEt/ℏ) while their position probabilities remain stationary. The free-particle kinetic energy is p²/(2m).',[
 f('eigenphase','Calculate energy-eigenstate phase','Complex phase; Energy and time','A stationary state can evolve in phase while its density stays fixed.',n=>num(`Use ℏ=1. An energy eigenstate has E=${n}, and evolves for t=0.5. Find the phase angle in exp(iθ), using θ=−Et rather than reducing modulo 2π.`,-n/2,'Use θ=−Et/ℏ.',`θ=−${n}×0.5=${-n/2}.`,'An eigenstate converts Schrödinger evolution into a scalar phase factor.','A positive phase sign violates the stated time-evolution convention.')),
 f('kinetic','Calculate free-particle kinetic energy','Momentum; Squares; Mass','The energy operator and its measured eigenvalue are different representations.',n=>num(`A nonrelativistic free particle has mass m=2 and momentum p=${2*n} in consistent units. Find its kinetic energy.`,n*n,'Use E=p²/(2m).',`E=${2*n}²/(2×2)=${n*n}.`,'The free Hamiltonian has only its quadratic kinetic term here.','p/(2m) omits the momentum square.')),
 f('relative-phase','Find relative phase in a two-energy superposition','Superposition; Eigenphases','A relative phase evolves with the energy difference.',n=>num(`In units ℏ=1, a superposition has energies E₀=2 and E₁=${n+2}. After t=0.25, find the phase of component 1 relative to component 0, without reducing modulo 2π.`,-n/4,'Use relative phase =−(E₁−E₀)t/ℏ.',`θ_rel=−(${n+2}−2)×0.25=${-n/4}.`,'The common energy offset contributes only global phase.','Using E₁ alone confuses absolute phase with relative phase.')),
 f('stationary','Distinguish amplitude evolution from density evolution','Modulus; Energy eigenstate','A time-dependent phase does not make an eigenstate probability density oscillate.',n=>choose(`ψ(x,t)=φ(x)exp(−i${n}t), with normalized energy eigenfunction φ and ℏ=1. Which density is correct?`,['|φ(x)|²','|φ(x)|²exp(−2nt)','|φ(x)|²cos²(nt)'],0,'The exponential factor has modulus one at all times.','Taking only the real part of a complex state or treating i as absent introduces false density changes.'))
]);
bank('quantum-bound-states-and-tunneling','A bound state remains spatially localized and has allowed discrete energies in ideal wells. An infinite one-dimensional well of length L has E_n=n²π²ℏ²/(2mL²), n=1,2,... . A finite barrier permits tunneling; the stated thick-barrier estimate T≈exp(−2κa) applies below barrier energy, with κ=sqrt(2m(V−E))/ℏ.',[
 f('well-levels','Calculate infinite-well energy ratios','Squares; Quantum-number indexing','The infinite well has no n=0 physical state.',n=>num(`An infinite well has ground energy E₁=2 eV. Find E_${n+1} in eV.`,2*(n+1)**2,'Use E_k=k²E₁.',`E_${n+1}=${n+1}²×2=${2*(n+1)**2} eV.`,'Boundary conditions permit discrete positive integer mode numbers.','Linear scaling with n is not the infinite-well spectrum.')),
 f('length-scaling','Apply the inverse-square confinement scale','Ratios; Powers','Increasing the well length decreases its energies.',n=>num(`A well has E₁=16 eV at length L. What is E₁ for length ${n+1}L, with the same mass?`,16/(n+1)**2,'Energy is proportional to 1/L².',`E₁_new=16/${n+1}²=${fmt(16/(n+1)**2)} eV.`,'Less confinement lowers the kinetic-energy scale.','Scaling by the length ratio rather than its inverse square reverses confinement behaviour.')),
 f('barrier-decay','Calculate an evanescent decay constant','Squares; Square roots; Consistent units','Below-barrier decay does not mean no transmitted amplitude.',n=>num(`Use units m=1 and ℏ=1. A rectangular barrier exceeds the particle energy by V−E=${n*n/2}. Find κ.`,n,'Use κ=√(2m(V−E))/ℏ.',`κ=√(2×1×${n*n/2})=${n}.`,'Below-barrier solutions have real exponential decay.','Using √(E−V) would describe a different oscillatory region.')),
 f('transmission','Use and qualify a thick-barrier estimate','Exponential decay; Barrier width','The simple exponential estimate omits a prefactor and is not an exact barrier formula.',n=>num(`For a sufficiently thick barrier, use the approximation T≈exp(−2κa) with κ=2 per metre and a=${n/2} m. Find estimated transmission probability.`,Math.exp(-2*n),'Insert κ and width into the given approximation.',`T≈exp(−2×2×${n/2})=exp(${-2*n})=${fmt(Math.exp(-2*n))}.`,'The transmitted probability is suppressed by the square of the decaying amplitude.','exp(−κa) is an amplitude factor, not this probability estimate.'))
]);
bank('quantum-spin-and-angular-momentum','Spin is intrinsic quantum angular momentum. For spin 1/2, Z measurement returns ±ℏ/2; X has a different orthonormal basis |±⟩=(|0⟩±|1⟩)/√2. Total angular momentum has squared magnitude j(j+1)ℏ² and component mℏ with m=−j,...,j.',[
 f('spin-expectation','Calculate a spin-component mean','Probability-weighted mean; ℏ units','Spin components are measured along a stated axis.',n=>num(`Use ℏ=1. A spin-1/2 preparation has P(S_z=+1/2)=${n/10}. Find ⟨S_z⟩.`,n/10-.5,'Average +1/2 and −1/2 with the given probabilities.',`⟨S_z⟩=(1/2)${n/10}−(1/2)(1−${n/10})=${fmt(n/10-.5)}.`,'A component mean weights the two possible eigenvalues.','The mean is not constrained to ±1/2, although single outcomes are.')),
 f('basis-change','Measure Z-prepared spin along X','Superposition; Basis overlaps','A definite Z spin does not imply a definite X spin.',n=>num(`Spin ${n} is prepared in |0⟩, the +Z eigenstate. Find P(+X) for |+⟩=(|0⟩+|1⟩)/√2.`,.5,'Use |⟨+|0⟩|².',`The overlap is 1/√2, so P(+X)=1/2.`,'X and Z spin components have different eigenbases.','Assigning probability one carries the definite value across an incompatible axis.')),
 f('magnitude','Calculate total angular-momentum magnitude','Squares; Square roots; Quantum number j','Magnitude is √(j(j+1))ℏ, not jℏ.',n=>num(`Use ℏ=1. An angular-momentum state has j=${n/2}. Find the magnitude associated with J².`,Math.sqrt((n/2)*(n/2+1)),'Use √(j(j+1))ℏ.',`|J|=√(${n/2}×${n/2+1})=${fmt(Math.sqrt((n/2)*(n/2+1)))}.`,'J² has eigenvalue j(j+1)ℏ².','mℏ is one component, not the total magnitude.')),
 f('multiplicity','Count possible component outcomes','Integer and half-integer sequences; Angular-momentum labels','There are 2j+1 component outcomes, not j outcomes.',n=>num(`For j=${n/2}, how many distinct J_z eigenvalues exist?`,n+1,'Count m=−j,−j+1,...,+j.',`Count=2j+1=2×${n/2}+1=${n+1}.`,'The magnetic quantum number changes in steps of one.','Including only positive m omits zero or negative outcomes.'))
]);
bank('quantum-density-matrices','A density matrix ρ represents both pure states and mixtures. It is Hermitian (equal to its conjugate transpose), positive and has trace one (diagonal entries sum to one). Measurement probabilities are Tr(Pρ), where P projects onto an outcome. Purity Tr(ρ²)=1 for a pure state and is lower for a mixed state.',[
 f('diagonal','Read probabilities from a diagonal density matrix','Matrix entries; Probability normalization','Diagonal entries give probabilities only in that stated basis.',n=>num(`In the Z basis, ρ=diag(${n/10},${1-n/10}). Find P(0).`,n/10,'Z-basis probability P(0) is ρ₀₀.',`P(0)=${n/10}.`,'The projector onto |0⟩ selects the first diagonal entry in Tr(Pρ).','An off-diagonal entry describes coherence, not this direct probability.')),
 f('purity','Compute purity of a mixture','Matrix multiplication; Trace; Squares','A trace-one matrix need not represent a pure state.',n=>{const p=n/10;return num(`ρ=diag(${p},${fmt(1-p)}). Find Tr(ρ²).`,p*p+(1-p)**2,'Square the diagonal entries and sum.',`Tr(ρ²)=${p}²+${fmt(1-p)}²=${fmt(p*p+(1-p)**2)}.`,'For a diagonal state its eigenvalues are the listed populations.','Squaring the trace gives one and misses the state’s mixedness.');}),
 f('coherence','Compute another-basis probability including coherence','Inner products; Density matrix; X basis','Off-diagonal coherence can change X-basis predictions without changing Z populations.',n=>{const c=n/20;return num(`ρ=[[0.5,${c}],[${c},0.5]] in the Z basis, with real entries. Find P(+) for |+⟩=(|0⟩+|1⟩)/√2.`,.5+c,'Evaluate ⟨+|ρ|+⟩ as half the sum of all four entries.',`P(+)=(0.5+${c}+${c}+0.5)/2=${fmt(.5+c)}.`,'Projection onto |+⟩ combines diagonal populations and real coherence.','Reading only ρ₀₀ gives a Z measurement rather than this X measurement.');}),
 f('validity','Check a candidate density matrix for positivity','Matrix eigenvalues; Trace','Trace one and Hermiticity do not guarantee positivity.',n=>choose(`A candidate has ρ=[[0.5,${.5+n/10}],[${.5+n/10},0.5]]. Is it valid?`,['Yes, because its trace is one.','No: one eigenvalue is negative.','Yes, because it is symmetric.'],1,`Eigenvalues are 0.5±${.5+n/10}; the smaller is ${fmt(-n/10)}. Positive density matrices cannot have a negative eigenvalue.`,'A state also needs positivity; negative eigenvalues produce negative probabilities in a suitable basis.'))
]);
bank('quantum-entanglement-and-correlations','Two-qubit states use |00⟩,|01⟩,|10⟩,|11⟩ in that order. Entanglement means the joint state cannot be a mixture of product states. Correlation ⟨Z⊗Z⟩ weights equal bits by +1 and unequal bits by −1. Perfect correlation in one basis alone does not establish entanglement or permit signalling.',[
 f('joint','Calculate joint outcomes for a Bell-like state','Tensor-product basis; Squared amplitudes','Joint probabilities differ from marginal probabilities.',n=>{const p=n/10;return num(`|ψ⟩=√${p}|00⟩+√${fmt(1-p)}|11⟩. Find the probability of joint outcome 00 in the Z basis.`,p,'Square the amplitude attached to |00⟩.',`P(00)=${p}; P(11)=${fmt(1-p)} and P(01)=P(10)=0.`,'The stated basis outcome is a complete two-qubit result.','P(A=0) happens to equal P(00) here, but marginals usually sum multiple joint outcomes.');}),
 f('conditional','Compute conditional correlations','Joint probability; Nonzero conditioning event','Knowing a remote result changes a conditional prediction but cannot control that result.',n=>num(`|ψ⟩=√${n/10}|00⟩+√${fmt(1-n/10)}|11⟩. After Z measurement finds Alice’s bit 0, find P(Bob’s bit 0 | Alice’s bit 0).`,1,'Use P(00)/P(A=0).',`P(B=0|A=0)=(${n/10})/(${n/10})=1.`,'Only 00 contributes to the nonzero conditioning event.','This conditional certainty does not let Alice choose her random outcome.')),
 f('correlation','Calculate a joint Pauli correlation','Expected values; Joint probabilities','A correlation of one in a basis is not by itself an entanglement test.',n=>{const q=n/10;return num(`A joint Z distribution has P(00)=P(11)=${fmt((1-q)/2)}, and P(01)=P(10)=${q/2}. Find ⟨Z⊗Z⟩.`,1-2*q,'Add equal-bit probabilities and subtract unequal-bit probabilities.',`⟨ZZ⟩=(1−${q})−${q}=${fmt(1-2*q)}.`,'Z assigns +1 to bit 0 and −1 to bit 1, so equal products are positive.','Adding all probabilities yields normalization, not correlation.');}),
 f('cross-basis','Compare quantum coherence with classical same-bit correlation','X basis; Bell state; Mixture','A classical same-bit mixture and a Bell state have different X correlations.',n=>{const v=n/10;return num(`Let ρ=v|Φ+⟩⟨Φ+|+(1−v)(|00⟩⟨00|+|11⟩⟨11|)/2, v=${v}, |Φ+⟩=(|00⟩+|11⟩)/√2. Find ⟨X⊗X⟩; X flips 0↔1.`,v,'Use linearity: Bell component has XX=1, same-bit mixture has XX=0.',`⟨XX⟩=${v}×1+(1−${v})×0=${v}.`,'X⊗X exchanges 00 and 11; coherent cross terms survive only in the Bell component.','Assigning one to the classical mixture uses Z correlation for an X measurement.');})
]);
bank('quantum-decoherence-and-noise','A quantum channel is a physical state update, including noise. Dephasing reduces coherence (off-diagonal entries) while preserving Z populations in the stated model. Bit flips exchange |0⟩ and |1⟩; amplitude damping transfers excitation to the ground state. Channel assumptions determine which probabilities change.',[
 f('dephase','Update a coherence under a supplied channel','Density matrices; Multiplication','Dephasing need not change measurement populations in its preferred basis.',n=>{const eta=n/10;return num(`ρ=[[0.5,0.4],[0.4,0.5]]. A pure-dephasing channel multiplies off-diagonal entries by η=${eta} and leaves diagonal entries fixed. Find the new upper off-diagonal entry.`,.4*eta,'Apply the given coherence factor only to the off-diagonal entry.',`ρ′₀₁=0.4×${eta}=${fmt(.4*eta)}.`,'The model defines how the environment suppresses relative-phase coherence.','Scaling the whole matrix would change trace and violate normalization.');}),
 f('bit-flip','Calculate population after random bit flips','Classical total probability; Pauli X','A bit-flip channel exchanges populations on flipped trials.',n=>{const p=n/10;return num(`A qubit is initially |0⟩. Independently, X is applied with probability p=${p}; otherwise nothing is applied. Find final P(1).`,p,'Only flipped trials turn |0⟩ into |1⟩.',`P(1)=p=${p}.`,'The channel combines the two trial probabilities.','Adding the two branch amplitudes would treat random noise as coherent control.');}),
 f('damping','Apply amplitude-damping population decay','Excited-state probability; Channel parameter','Amplitude damping changes excited population rather than just relative phase.',n=>{const g=n/10;return num(`Initial excited-state population is 0.8. An amplitude-damping channel has decay probability γ=${g} for an excitation. Find final excited population.`,.8*(1-g),'Use p₁′=(1−γ)p₁.',`p₁′=(1−${g})×0.8=${fmt(.8*(1-g))}.`,'Only surviving excitations remain in |1⟩.','Subtracting γ directly ignores that only the excited fraction can decay.');}),
 f('coherence-observable','Predict how dephasing changes an X measurement','Density matrix; X-basis projector','A lost X signal does not imply the Z populations changed.',n=>{const eta=n/10;return num(`Start in |+⟩, so ρ=[[0.5,0.5],[0.5,0.5]]. Dephasing keeps diagonal entries and multiplies off-diagonals by η=${eta}. Find P(+) afterward.`,.5*(1+eta),'Use P(+)=(ρ₀₀+ρ₁₁+ρ₀₁+ρ₁₀)/2.',`P(+)=(1+${eta})/2=${fmt(.5*(1+eta))}.`,'The X-basis signal includes coherence that dephasing reduces.','Keeping P(+)=1 ignores the loss of coherence.');})
]);
bank('quantum-quantum-information','A qubit is a normalized two-level quantum state. X swaps its basis states; H (Hadamard) maps |0⟩ to |+⟩ and |1⟩ to |−⟩. Controlled-X flips its target only for control 1. Fidelity with a pure target |φ⟩ is ⟨φ|ρ|φ⟩ here; do not assume unknown quantum states can be copied.',[
 f('gate','Compute a gate’s basis-state effect','Qubit basis; Matrix-vector multiplication','A gate acts on amplitudes, not a preselected classical outcome.',n=>num(`Prepare a qubit with P(0)=${n/10}, P(1)=${fmt(1-n/10)} in the Z basis. Apply X. Find the new P(0).`,1-n/10,'X exchanges the |0⟩ and |1⟩ amplitudes.',`P_new(0)=P_old(1)=${fmt(1-n/10)}.`,'A deterministic basis swap exchanges the associated probabilities.','X is not a measurement and does not randomly choose an outcome.')),
 f('hadamard','Interfere amplitudes through a Hadamard gate','Superposition; Normalization; Inner products','H changes measurement probabilities by combining amplitudes.',n=>{const a=1,b=n;return num(`|ψ⟩=(|0⟩+${b}|1⟩)/√${1+b*b}. Apply H=[[1,1],[1,−1]]/√2. Find P(0).`,(a+b)**2/(2*(1+b*b)),'The new |0⟩ amplitude is (1+n)/√(2(1+n²)).',`P(0)=${(1+b)**2}/${2*(1+b*b)}=${fmt((1+b)**2/(2*(1+b*b)))}.`,'The two original amplitudes add coherently in this output.','Averaging input probabilities omits the amplitude cross term.');}),
 f('controlled','Apply a controlled-X truth table','Two-qubit basis order; Conditional gate','The control is not flipped by controlled-X.',n=>{if(n===5)return txt('A circuit starts in |10⟩ and applies controlled-X twice, with first qubit control. What output bits should a deterministic Z readout show?',['10','|10⟩'],'Track the target after each of the two flips.','|10⟩→|11⟩→|10⟩.','Controlled-X is its own inverse; two identical flips restore the target.','One flip would yield 11, but the circuit specifies two.');if(n===6)return txt('A controlled-X with first qubit control outputs |11⟩. Which input basis bits produced this output?',['10','|10⟩'],'Reverse the operation using the same gate.','|10⟩ maps to |11⟩.','Controlled-X is its own inverse, so reversing it also flips the target when the control is 1.','The unchanged control remains 1.');const bits=['00','01','10','11'],s=bits[n-1],out=s[0]==='1'?s[0]+(s[1]==='0'?'1':'0'):s;return txt(`Apply controlled-X with first bit control and second bit target to |${s}⟩. Enter the output bits.`,[out,`|${out}⟩`],'Flip only the target when the control is 1.',`|${s}⟩ → |${out}⟩.`,'The supplied control-target order fixes the gate action.','Flipping the control reverses the specified gate roles.');}),
 f('fidelity','Calculate fidelity to a pure target','Density matrices; State overlap','The convention here uses squared-overlap fidelity, not its square root.',n=>{const p=n/10;return num(`A noisy output is ρ=diag(${p},${fmt(1-p)}). Target is |0⟩. Using F=⟨0|ρ|0⟩, find fidelity.`,p,'Project the density matrix onto the pure target.',`F=ρ₀₀=${p}.`,'The stated convention directly measures target outcome weight.','Taking √p would use a different fidelity convention.');})
]);
bank('quantum-hydrogen-and-orbitals','For ideal nonrelativistic hydrogen without fine structure, E_n=−13.6 eV/n². An orbital is a spatial wavefunction, not a planetary path. Quantum labels obey n≥1, l=0,...,n−1 and m_l=−l,...,l. Degeneracies here ignore magnetic fields and include spin only when explicitly requested.',[
 f('energy','Calculate ideal hydrogen energy levels','Squares; Signed energies','A negative bound-state energy is measured relative to the free-particle threshold.',n=>num(`In ideal hydrogen E_k=−13.6/k² eV. Find E_${n+1} in eV, ignoring fine structure.`, -13.6/(n+1)**2,'Substitute the positive integer principal quantum number.',`E_${n+1}=−13.6/${n+1}²=${fmt(-13.6/(n+1)**2)} eV.`,'The attractive Coulomb bound spectrum approaches zero from below.','The level closest to zero has less binding, not a more negative energy.')),
 f('transition','Calculate a hydrogen transition energy','Hydrogen spectrum; Energy differences','A transition photon energy is the magnitude of the atomic energy change.',n=>num(`Ideal hydrogen emits a photon in a transition from n=${n+1} to n=1. Find the photon energy in eV.`,13.6*(1-1/(n+1)**2),'Subtract final atomic energy from initial atomic energy.',`E_photon=−13.6/${n+1}²−(−13.6)=${fmt(13.6*(1-1/(n+1)**2))} eV.`,'The downward transition releases the atom’s energy decrease.','Adding the magnitudes of both levels overcounts the released energy.')),
 f('labels','Count magnetic orbital orientations','Integer sequences; Angular-momentum labels','m_l has 2l+1 values including negative values.',n=>num(`An orbital has angular-momentum label l=${n}. How many distinct m_l values are allowed, ignoring spin?`,2*n+1,'Count integers from −l through +l.',`Count=2×${n}+1=${2*n+1}.`,'Each m_l labels a different component eigenvalue.','Including spin doubles the count, but spin was explicitly excluded here.')),
 f('shell','Count orbital states in a principal shell','Allowed l and m_l; Finite sums','Orbital state count n² excludes the electron’s two spin labels.',n=>num(`For principal shell n=${n}, count spatial hydrogen orbital states over all l and m_l, ignoring spin.`,n*n,'Sum 2l+1 for l=0,...,n−1.',`1+3+...+${2*n-1}=${n*n}.`,'The sum of the first n odd positive integers is n².','2n² includes spin states and is not the requested spatial count.'))
]);
bank('quantum-identical-particles','Identical particles cannot be given physically distinguishing labels. Bosonic total states are symmetric under exchange; fermionic total states are antisymmetric, including spatial and spin parts together. The Pauli principle prevents identical fermions from occupying the same complete one-particle state; opposite spins can share one spatial orbital.',[
 f('fermion-count','Count fermion occupations of distinct modes','Combinations; Occupied-or-empty modes','The complete mode includes spin if relevant.',n=>{const modes=n+2;return num(`Two identical fermions occupy ${modes} distinct complete one-particle modes with no interaction. How many occupation configurations exist?`,modes*(modes-1)/2,'Choose two different occupied modes; order does not matter.',`Count=C(${modes},2)=${modes}×${modes-1}/2=${modes*(modes-1)/2}.`,'Pauli exclusion permits at most one fermion per complete mode.','Counting ordered particle labels doubles configurations that are physically identical.');}),
 f('boson-count','Count two-boson occupations allowing a shared mode','Combinations with repetition; Identical particles','Bosons may share a complete one-particle mode.',n=>{const modes=n+2;return num(`Two identical bosons occupy ${modes} distinct one-particle modes. Count occupation configurations, allowing both in the same mode.`,modes*(modes+1)/2,'Count distinct-mode pairs plus one double-occupation case per mode.',`C(${modes},2)+${modes}=${modes}(${modes}+1)/2=${modes*(modes+1)/2}.`,'Exchange does not produce a new occupation configuration.','Using the fermion count omits the allowed same-mode occupations.');}),
 f('exchange','Apply symmetry of a two-particle state','Two-particle products; Relative signs','Antisymmetry concerns the full state rather than the spatial factor alone.',n=>choose(`Distinct orthogonal complete modes are |a_${n}⟩ and |b_${n}⟩. Which normalized state describes two identical fermions in these modes?`,['(|ab⟩+|ba⟩)/√2','(|ab⟩−|ba⟩)/√2','|aa⟩'],1,'Swapping the complete particle coordinates changes the antisymmetric state’s sign.','The plus combination is symmetric; same complete-mode fermion occupation vanishes.')),
 f('spin-orbitals','Count electron capacity with explicit spin modes','Pauli principle; Two spin labels','Two electrons may share a spatial orbital when their complete spin-orbital states differ.',n=>num(`There are ${n+1} orthogonal spatial orbitals, each supporting two spin modes. What is the maximum electron count under Pauli exclusion?`,2*(n+1),'Allow one electron per complete spin-orbital mode.',`Maximum=2×${n+1}=${2*(n+1)}.`,'Opposite spins create two different complete states for each spatial orbital.','Forbidding all shared spatial orbitals incorrectly omits allowed opposite-spin pairs.'))
]);
bank('quantum-approximation-methods','Perturbation theory approximates a slightly changed Hamiltonian using a known basis. For a nondegenerate level, first-order energy change is ⟨n|V|n⟩. The variational method evaluates an energy expectation in a normalized trial state and gives an upper bound to ground energy. Check correction size and degeneracy before trusting an approximation.',[
 f('first-order','Calculate a nondegenerate first-order energy correction','Matrix diagonal elements; Small perturbation','First-order energy uses a diagonal expectation, not an off-diagonal coupling.',n=>num(`A nondegenerate reference state has E₀=2 eV. A small perturbation has expectation ⟨V⟩=${n/100} eV in that state. Find first-order corrected energy.`,2+n/100,'Use E≈E₀+⟨V⟩.',`E≈2+${n/100}=${fmt(2+n/100)} eV.`,'First-order nondegenerate theory uses the unperturbed state’s diagonal expectation.','Changing the state before evaluating this expectation mixes orders of approximation.')),
 f('second-order','Use a supplied second-order nondegenerate correction','Squared coupling; Energy gaps','For a ground level coupled to a higher level the second-order correction is negative.',n=>num(`A ground state E₀=0 eV couples to one higher state E₁=10 eV with matrix element V₁₀=${n/10} eV. No other couplings exist. Find second-order ΔE₀=|V₁₀|²/(E₀−E₁) in eV.`,-((n/10)**2)/10,'Square the coupling and divide by the signed energy difference.',`ΔE₀=(${n/10})²/(0−10)=${fmt(-((n/10)**2)/10)} eV.`,'The higher-state denominator is negative for the ground state.','Using the absolute gap loses the correction’s sign.')),
 f('variational','Minimize a trial-energy function and identify its bound','Derivatives; Positive parameter; Second derivative','A variational estimate bounds the true ground energy from above.',n=>num(`A normalized trial family has energy E(a)=a+${n*n}/a in chosen units, with a>0. Find the minimizing a.`,n,'Set E′=1−n²/a²=0 and use a>0.',`a=${n}; E″=2×${n*n}/a³>0, and E grows at both boundaries.`,'A minimum over this trial family is the best upper bound available from the family.','The variational minimum is not automatically the exact ground energy.')),
 f('validity','Assess perturbation size relative to a level gap','Ratios; Level separation; Nondegeneracy','Small compared with absolute energy is not the same as small compared with relevant gaps.',n=>num(`An off-diagonal perturbation coupling is ${n/100} eV and the relevant nondegenerate level gap is 2 eV. Find coupling/gap, a diagnostic for perturbative smallness.`,n/200,'Compare the matrix-element magnitude with the gap.',`Ratio=(${n/100})/2=${n/200}.`,'Small coupling-to-gap ratios limit mixing of the reference states.','A nearly degenerate gap requires a different treatment even if all absolute energies are large.'))
]);
// Contextual applications are kept distinct from calculation drills. These
// replace the existing stable task at that objective rather than adding a quota.
function application(topicId:string,key:string,draft:Draft) {
 const b=stemBanks[topicId],id=`${topicId}:${key}:application:v1`;
 const index=b.exercises.findIndex(e=>e.id===id);
 if(index<0)throw new Error(`Unknown authored application ${id}`);
 b.exercises[index]={id,objectiveId:`${topicId}:${key}`,purpose:'application',difficulty:'core',...draft};
}
application('math-functions-and-graphs','inverse',num('A thermostat converts Celsius input C to Fahrenheit output F=1.8C+32. What Celsius setting produces 77°F?',25,'Solve 1.8C+32=77 by subtracting 32 then dividing by 1.8.','C=(77−32)/1.8=25°C.','The inverse finds the input that produces the desired output.','Applying the forward conversion to 77 treats Fahrenheit as Celsius.'));
application('math-polynomial-patterns','expand',txt('A designer makes a rectangular panel with sides (x+5) cm and (x+2) cm, x≥0. Expand its area in cm² using x^2 notation.',['x^2+7x+10','x^2 + 7x + 10'],'Area is the product of the two side lengths.','A=(x+5)(x+2)=x²+7x+10.','Distributing all four products counts the full area.','x²+10 omits both cross rectangles.'));
application('math-limits-and-continuity','continuity',num('A calibrated sensor reports R(t)=(t²−25)/(t−5) for t≠5. Firmware must define R(5) so the ideal model has no jump or hole. What value should be stored?',10,'Find the limit and set the missing point equal to it.','R(t)=t+5 for t≠5; lim t→5 R(t)=10.','The removable hole is filled by matching the nearby readings.','Storing 0 because both original terms vanish ignores their ratio near the point.'));
application('math-sequences-and-series','finite-sum',num('A savings plan deposits 10 dollars in week 1 and increases the weekly deposit by 10 dollars through week 8. With no interest or withdrawals, find total dollars deposited.',360,'Sum the arithmetic series with 8 terms, first 10 and last 80.','Total=8(10+80)/2=360 dollars.','Endpoint pairing gives the average deposit times the number of deposits.','80 is only the final weekly deposit.'));
application('math-vectors-and-matrices','matrix-product',txt('A graphics pipeline first applies B=[[3,1],[1,2]] to column vectors, then A=[[1,2],[2,1]]. Find the composite matrix AB, entering [[a,b],[c,d]].',['[[5,5],[7,4]]','[[5, 5], [7, 4]]'],'The later transform acts on the left: A(Bv)=(AB)v.','AB=[[1×3+2×1,1×1+2×2],[2×3+1×1,2×1+1×2]]=[[5,5],[7,4]].','Column-vector composition fixes the multiplication order.','BA represents applying A first, then B, a different pipeline.'));
application('math-proofs-and-optimization','constraint',num('A grower has 24 m of fencing for all four sides of a rectangular bed. What width in m maximizes area, allowing real positive dimensions?',6,'Let the other side be 12−x; maximize A=x(12−x).','A′=12−2x=0 gives x=6; A″=−2 and endpoint areas are zero.','The perimeter constraint makes area a concave quadratic.','Using 12 m as a side leaves no length for the other side.'));
application('quantum-complex-numbers','phase',num('An interferometer is calibrated so amplitudes at a detector are (1+exp(iθ))/2. Its phase shifter sets θ=π/2. Find the detector probability predicted by this ideal coherent model.',.5,'Add the complex amplitudes before squaring their modulus.','A=(1+i)/2; |A|²=(1²+1²)/4=0.5.','The phase shifter changes the relative phase between indistinguishable paths.','Adding separate path probabilities would miss phase dependence.'));
application('quantum-wavefunctions-and-probability','interval',num('An ideal position detector accepts the first 0.5 m of a box of length 2 m. A prepared particle has uniform density 1/2 per metre in the box. Find the detection probability.',.25,'Integrate the density over the accepted interval.','P=(1/2)×0.5=0.25.','The detector window selects an interval rather than an exact point.','Half a metre is one quarter of this box, not one half.'));
application('quantum-superposition','phase',num('A Ramsey measurement uses |ψ⟩=(|0⟩+exp(iθ)|1⟩)/√2 and reads out in the X basis. At θ=π/3, what is the ideal probability of the + outcome?',.75,'Use the overlap with |+⟩=(|0⟩+|1⟩)/√2.','P(+)=(1+cos(π/3))/2=(1+1/2)/2=0.75.','The basis rotation makes relative phase visible as a detector probability.','Z-basis probabilities stay at one half and do not answer this readout.'));
application('quantum-measurement-outcomes','mean',num('A calibrated quantum sensor produces +2 units with probability 0.8 and −2 units with probability 0.2. What mean signal should many independent preparations approach?',1.2,'Compute the probability-weighted outcome mean.','⟨A⟩=2×0.8−2×0.2=1.2 units.','The mean predicts the average signal over repeated preparations.','The mean 1.2 need not be a possible individual readout.'));
application('quantum-uncertainty-relations','position-momentum',num('An imaging model prepares a canonical position-momentum state with Δx=0.25 in units ℏ=1. What minimum momentum standard deviation must a physically possible design allow?',2,'Use Δp≥ℏ/(2Δx).','Δp≥1/(2×0.25)=2.','The preparation spreads must satisfy the commutation bound.','Reducing detector error cannot remove this lower bound on the state’s momentum spread.'));
application('quantum-schrodinger-equation','relative-phase',num('A two-energy interferometer has E₀=1 and E₁=3 in units ℏ=1. It evolves for 0.5 time units. Find the relative phase of component 1 versus component 0, without reducing modulo 2π.',-1,'Use θ_rel=−(E₁−E₀)t/ℏ.','θ_rel=−(3−1)×0.5=−1 rad.','A common energy phase cancels while the energy difference drives the interference phase.','Using only E₁ gives the absolute phase, not the relative phase.'));
application('quantum-spin-and-angular-momentum','spin-expectation',num('A spin-polarization monitor receives identically prepared spin-1/2 particles. In units ℏ=1, 70% of ideal Z readings are +1/2 and 30% are −1/2. Find the predicted average S_z.',.2,'Weight the two signed component outcomes.','⟨S_z⟩=0.7/2−0.3/2=0.2.','The average quantifies polarization of the preparation along Z.','The fractions are outcome probabilities, not amplitudes to square again.'));
application('quantum-density-matrices','coherence',num('Tomography estimates ρ=[[0.5,0.2],[0.2,0.5]] for a qubit. An independent apparatus measures X. What + outcome probability should validate this ideal model?',.7,'Project ρ onto |+⟩=(|0⟩+|1⟩)/√2.','P(+)=(0.5+0.2+0.2+0.5)/2=0.7.','The X measurement tests real coherence as well as populations.','Using only the first diagonal entry tests Z, not X.'));
application('quantum-entanglement-and-correlations','correlation',num('A pair-source test records Z outcomes with probabilities P(00)=0.4, P(11)=0.4, P(01)=0.1, P(10)=0.1. Find ⟨Z⊗Z⟩. These data alone do not certify entanglement.',.6,'Assign +1 to equal-bit pairs and −1 to unequal-bit pairs.','⟨ZZ⟩=0.4+0.4−0.1−0.1=0.6.','Correlation measures the mean product of the two signed outcomes.','A high same-basis correlation alone is also possible with classical correlated mixtures.'));
application('quantum-decoherence-and-noise','coherence-observable',num('A phase-memory device starts in |+⟩. Calibration finds pure dephasing keeps Z populations fixed and reduces off-diagonal entries by factor 0.6. Find the predicted +X readout probability.',.8,'After dephasing, diagonal entries are 0.5 and off-diagonals are 0.3.','P(+)=0.5+0.3=0.8.','The X readout is sensitive to the surviving real coherence.','The unchanged Z populations do not imply unchanged X probability.'));
application('quantum-hydrogen-and-orbitals','transition',num('An ideal hydrogen spectrometer records emission from n=3 to n=2. Using E_n=−13.6/n² eV and ignoring fine structure, find the photon energy in eV.',13.6*(1/4-1/9),'Subtract the final atomic energy from the initial atomic energy.','E_photon=−13.6/9−(−13.6/4)=13.6(1/4−1/9)='+fmt(13.6*(1/4-1/9))+' eV.','The photon carries the atom’s lost energy.','Using the ground state as the final level predicts a different spectral line.'));
application('quantum-identical-particles','spin-orbitals',num('An ideal electron-trap model has three available spatial orbitals, each with two spin modes, and neglects interactions. What maximum electron count can occupy these modes?',6,'Count distinct complete spin-orbital modes.','3 spatial orbitals × 2 spin modes = 6 modes, each allowing one electron.','Pauli exclusion limits complete states rather than spatial orbitals alone.','Three is the orbital count, not the electron capacity when both spin modes are available.'));
application('quantum-approximation-methods','validity',num('A device-model designer estimates coupling 0.04 eV between two nondegenerate levels separated by 2 eV. Find coupling/gap as a first diagnostic before using perturbation theory.',.02,'Divide the coupling magnitude by the relevant energy gap.','0.04/2=0.02.','Mixing is controlled by this ratio; a small ratio supports but does not prove the approximation.','Comparing with a large absolute reference energy can hide a small relevant gap.'));
// Label only the contextual task selected above (or an existing physical model)
// as application. Other n=5 samples remain independent calculations.
const contextualObjective:Record<string,string>={
 'math-whole-number-operations':'groups','math-fractions-and-decimals':'decimals','math-ratios-and-rates':'rate-model','math-equations-and-inequalities':'model','math-coordinates-and-graphs':'distance','math-geometry-and-measurement':'volume','math-data-and-probability':'independence','math-functions-and-graphs':'inverse','math-polynomial-patterns':'expand','math-exponential-models':'growth','math-trigonometric-relationships':'height','math-limits-and-continuity':'continuity','math-derivatives-and-integrals':'accumulation','math-sequences-and-series':'finite-sum','math-vectors-and-matrices':'matrix-product','math-proofs-and-optimization':'constraint',
 'physics-units-and-measurement':'uncertainty','physics-vectors-and-motion':'position','physics-forces-and-free-bodies':'net-force','physics-work-and-energy':'conservation','physics-momentum-and-collisions':'inelastic','physics-rotation-and-torque':'torque','physics-oscillations-and-waves':'speed','physics-fluids-and-flow':'continuity','physics-heat-and-thermodynamics':'efficiency','physics-electric-fields-and-potential':'field','physics-circuits-and-magnetism':'power','physics-light-and-optics':'lens','physics-relativity-and-modern-physics':'time','physics-quantum-models':'photoelectric','physics-statistical-physics':'averages','physics-computational-physics':'convergence',
 'quantum-complex-numbers':'phase','quantum-probability-and-waves':'counts','quantum-wavefunctions-and-probability':'interval','quantum-superposition':'phase','quantum-measurement-outcomes':'mean','quantum-uncertainty-relations':'position-momentum','quantum-schrodinger-equation':'relative-phase','quantum-bound-states-and-tunneling':'transmission','quantum-spin-and-angular-momentum':'spin-expectation','quantum-density-matrices':'coherence','quantum-entanglement-and-correlations':'correlation','quantum-decoherence-and-noise':'coherence-observable','quantum-quantum-information':'controlled','quantum-hydrogen-and-orbitals':'transition','quantum-identical-particles':'spin-orbitals','quantum-approximation-methods':'validity'
};
for(const b of Object.values(stemBanks)) {
 const chosen=`${b.topicId}:${contextualObjective[b.topicId]}`;
 for(const e of b.exercises)if(e.purpose==='application'&&e.objectiveId!==chosen&&!e.id.includes(':extra-'))e.purpose='independent';
}
function extension(topicId:string,key:string,slug:string,draft:Draft) {
 const b=stemBanks[topicId];
 b.exercises.push({id:`${topicId}:${key}:${slug}:v1`,objectiveId:`${topicId}:${key}`,purpose:'transfer',difficulty:'extension',...draft});
}
// Further cases address assumptions that a routine calculation cannot reveal.
stemBanks['physics-fluids-and-flow'].objectives[2].title='Apply continuity and a lossless flow-energy balance';
extension('physics-fluids-and-flow','continuity','bernoulli',num('Water of density 1000 kg/m³ flows steadily through a horizontal pipe. Speed increases from 2 to 4 m/s. Neglect viscosity and apply Bernoulli along one streamline. Find p₂−p₁ in Pa.',-6000,'At equal height, p₁+ρv₁²/2=p₂+ρv₂²/2.','p₂−p₁=(1000/2)(2²−4²)=−6000 Pa.','The kinetic-energy density increase is balanced by a pressure decrease in this ideal model.','This relation cannot account for viscous pressure losses or arbitrary points off the same streamline.'));
stemBanks['physics-relativity-and-modern-physics'].objectives[3].title='Distinguish rest, total and kinetic energies';
extension('physics-relativity-and-modern-physics','rest-energy','kinetic',num('A moving particle has rest energy mc²=8 MeV and speed 0.6c. Find its relativistic kinetic energy in MeV.',2,'Use γ=1/√(1−0.6²)=1.25 and K=(γ−1)mc².','K=(1.25−1)×8=2 MeV.','Subtracting rest energy from total energy γmc² isolates motion-related energy.','10 MeV is total energy, whereas the requested kinetic energy is 2 MeV.'));
stemBanks['physics-heat-and-thermodynamics'].objectives[3].title='Calculate efficiency and reservoir entropy changes';
extension('physics-heat-and-thermodynamics','efficiency','reservoir-entropy',num('An ideal large reservoir at constant 300 K receives 600 J of heat. Find its entropy change in J/K. Treat the reservoir equilibrium change as ΔS=Q_received/T.',2,'Divide heat received by the reservoir absolute temperature.','ΔS=600/300=2 J/K.','The large reservoir remains at a fixed temperature, allowing this equilibrium entropy-change calculation.','This is the reservoir entropy change; an entire process may also generate entropy and requires a full-system balance.'));
stemBanks['quantum-density-matrices'].objectives[2].title='Compute coherence and reduce a joint state';
extension('quantum-density-matrices','coherence','partial-trace',txt('For |ψ⟩=(|00⟩+|11⟩)/√2, find the reduced density matrix of the first qubit by tracing out the second. Enter [[a,b],[c,d]].',['[[0.5,0],[0,0.5]]','[[0.5, 0], [0, 0.5]]'],'In ρ_A, sum ⟨b|ρ_AB|b⟩ over b=0,1 of the second qubit.','The diagonal terms become (|0⟩⟨0|+|1⟩⟨1|)/2; cross terms vanish because ⟨0|1⟩=0.','The partial trace preserves first-qubit predictions while discarding the unavailable subsystem.','The joint state is pure, but the reduced qubit is mixed; replacing it with |+⟩ would predict incorrect X results.'));
stemBanks['quantum-approximation-methods'].objectives[0].title='Use first-order theory and recognize a degenerate exception';
extension('quantum-approximation-methods','first-order','degenerate',txt('Two unperturbed states share energy 5 eV. Within that degenerate subspace, V=[[0,0.1],[0.1,0]] eV. Find first-order corrected energies in increasing order, separated by a comma.',['4.9,5.1','4.9, 5.1'],'Diagonalize the perturbation inside the degenerate subspace.','V has eigenvalues −0.1 and +0.1 eV, so energies become 4.9 and 5.1 eV.','At degeneracy off-diagonal coupling must be resolved before assigning first-order energy shifts.','Taking only the zero diagonal entries incorrectly predicts no splitting.'));
stemBanks['quantum-entanglement-and-correlations'].objectives[3].title='Compare cross-basis correlations and a supplied Bell statistic';
extension('quantum-entanglement-and-correlations','cross-basis','chsh',num('A Bell experiment defines S=|E(A,B)+E(A,B′)+E(A′,B)−E(A′,B′)|. The correlations are 1/√2,1/√2,1/√2,−1/√2 respectively. Find S. For the stated CHSH statistic, local models satisfying the usual measurement-independence assumptions have S≤2.',2*Math.sqrt(2),'Substitute all four signed correlations before taking the absolute value.','S=|1/√2+1/√2+1/√2−(−1/√2)|=2√2='+fmt(2*Math.sqrt(2))+'.','The negative fourth correlation contributes positively because its coefficient in S is negative.','Do not infer signalling or a loophole-free experiment from four ideal correlations; experimental conclusions also depend on sampling and independence assumptions.'));
extension('math-derivatives-and-integrals','definite','signed-area',num('Evaluate ∫ from −1 to 1 of x³ dx. Enter the signed integral value.',0,'An antiderivative is x⁴/4.','F(1)−F(−1)=1/4−1/4=0; the total geometric area is ∫|x³|dx=1/2.','Opposite signed contributions cancel in the definite integral.','A zero integral does not say the curve has zero total geometric area.'));
stemBanks['quantum-density-matrices'].scope+=' A reduced state retains one subsystem’s predictions by summing over the unobserved subsystem; this operation is called a partial trace. Matrix eigenvalues are the scalars by which a matrix scales its eigenvectors.';
stemBanks['quantum-approximation-methods'].scope+=' The Hamiltonian is the energy operator. Degenerate states share the same reference energy; their subspace consists of all their linear combinations. Diagonalizing the perturbation means finding combinations in that subspace that receive definite first-order shifts.';
stemBanks['quantum-entanglement-and-correlations'].scope+=' The optional CHSH calculation combines four correlations from different measurement settings. Its local bound assumes, among other conditions, that the choice of settings is independent of hidden variables used by the model; ideal arithmetic alone cannot certify an experimental violation.';
stemBanks['physics-heat-and-thermodynamics'].scope+=' Entropy tracks the distribution of energy and the direction of thermodynamic processes; a large equilibrium reservoir gaining heat Q at fixed absolute temperature T changes entropy by Q/T.';
